Translate("deDE", "medivh", {
	title = "Medivh",
	subtitle = "Der letzte Wächter von Tirisfal",
	allegiance = "Orden von Tirisfal · Karazhan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Medivh war der letzte {link:the-night-watch}Wächter{/link} von {link:tirisfal-glades}Tirisfal{/link}, der geheime Streiter, den die weisesten Magier der Welt mit Macht ausstatteten, um der {link:burning-legion}Brennenden Legion{/link} entgegenzutreten. Er war der Sohn der Wächterin {link:aegwynn}Aegwynn{/link} und von Nielas Aran, dem Hofbeschwörer von {link:stormwind-city}Stormwind{/link}. Er war auch der liebste Freund von König {link:llane-wrynn}Llane Wrynn{/link} und von Sir {link:anduin-lothar}Anduin Lothar{/link}. Doch die Macht, die {link:azeroth}Azeroth{/link} hätte schützen sollen, war vergiftet, bevor er seinen ersten Atemzug tat, und Medivh war es, der den {link:orcs}Orcs{/link} den Weg öffnete.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Kein Sterblicher tat mehr, um das Zeitalter des Krieges herbeizuführen. Durch Medivh griff der Dämonenfürst {link:sargeras}Sargeras{/link} in die Welt und hetzte die {link:horde}Horde{/link} auf die Königreiche der {link:humans}Menschen{/link}. Der {link:first-war}Erste Krieg{/link}, der Fall von {link:stormwind-city}Stormwind{/link} und jeder Krieg, der folgte, haben ihre Wurzeln in dem Turm, in dem er lebte.]=],
		},
		{
			title = "Eine vergiftete Geburt",
			text = [=[{link:aegwynn}Aegwynn{/link} wollte, dass ihr Sohn ihr Erbe werde, frei von dem Rat, der sie hatte beherrschen wollen. Sie wusste nicht, dass {link:sargeras}Sargeras{/link} seinen Geist in ihr verborgen hatte, seit dem Tag, an dem sie seinen Avatar niederstreckte. Als Medivh empfangen wurde, ging der Dämonenfürst in das ungeborene Kind über. Der Knabe wuchs klug und sanft heran, und er durchstreifte mit {link:llane-wrynn}Llane{/link} und {link:anduin-lothar}Lothar{/link} die Wälder des Königreichs. Als er vierzehn war, erwachte die Macht des Wächters in ihm und mit ihr die Dunkelheit, die darunter lag. Medivh fiel in einen Schlaf, den kein Heiler brechen konnte. Jahrelang lag er in der Obhut der Geistlichen der {link:northshire-abbey}Abtei von Nordhain{/link}. Als er erwachte, war er ein erwachsener Mann, und er sagte nichts von dem, was er in der Dunkelheit gesehen hatte.]=],
		},
		{
			title = "Karazhan",
			text = [=[Medivh schlug sein Heim in {link:karazhan}Karazhan{/link} auf, einem einsamen Turm in dem Land, das man heute den {link:deadwind-pass}Gebirgspass der Totenwinde{/link} nennt. Dort, geleitet von dem Willen, der in ihm lebte, griff er über die Leere hinweg nach einer sterbenden Welt namens {red:draenor}Draenor{/red}. Er fand den Hexenmeister der {link:orcs}Orcs{/link} {link:gul-dan}Gul'dan{/link}, und gemeinsam öffneten sie das {link:dark-portal}Dunkle Portal{/link}. Die {link:kirin-tor}Kirin Tor{/link} von {link:dalaran}Dalaran{/link} schickten ihm einen jungen Lehrling, {link:khadgar}Khadgar{/link}, der zu fürchten begann, was er im Turm sah. Auch die Halborcin {link:garona}Garona{/link} kam als Gesandte der {link:horde}Horde{/link} nach Karazhan. Durch Khadgar und Garona erreichte die Wahrheit endlich {link:stormwind-city}Stormwind{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• In seiner Jugend erhob er seine Macht an der Seite von {link:llane-wrynn}Llane{/link} und {link:anduin-lothar}Lothar{/link} gegen die {link:trolls}Trolle{/link} des Südens.
• Er öffnete das Dunkle Portal mit {link:gul-dan}Gul'dan{/link} und den Hexenmeistern von Draenor.
• Er nahm {link:khadgar}Khadgar{/link} als Lehrling an und ließ ihn mehr erfahren, als er preisgeben wollte.
• Er sah von seinem Turm aus zu, wie die {link:horde}Horde{/link} das Königreich seiner ältesten Freunde niederbrannte.]=],
		},
		{
			title = "Schicksal",
			text = [=[{link:anduin-lothar}Anduin Lothar{/link} und {link:khadgar}Khadgar{/link} erklommen {link:karazhan}Karazhan{/link}, um den Krieg an seiner Wurzel zu beenden. Mit Garonas Hilfe stellten sie den {link:the-night-watch}Wächter{/link}, und dort wurde Medivh erschlagen. Im Augenblick seines Todes versuchte {link:gul-dan}Gul'dan{/link}, die Geheimnisse des Grabmals von {link:sargeras}Sargeras{/link} aus seinem sterbenden Geist zu reißen, und wurde zum Lohn dafür in eine lange Starre geworfen. Medivh ist tot. Sein Turm steht leer und stumm über dem {link:deadwind-pass}Gebirgspass der Totenwinde{/link}, und das Volk des {link:duskwood}Dämmerwalds{/link} sagt, dass in seinen Fenstern noch immer seltsame Lichter brennen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Was Medivh wusste, was er wählte und was {link:sargeras}Sargeras{/link} für ihn wählte, lässt sich heute nicht mehr auseinanderhalten. Die Chroniken lassen diese Frage offen.]=],
		},
	},
	bonds = {
		{ id = "aegwynn", name = "Aegwynn", note = "seine Mutter" },
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "sein Jugendfreund" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "Freund und sein Mörder" },
		{ id = "gul-dan", name = "Gul'dan", note = "öffnete mit ihm das Dunkle Portal" },
		{ id = "khadgar", name = "Khadgar", note = "sein Lehrling" },
	},
})

Translate("deDE", "aegwynn", {
	title = "Aegwynn",
	subtitle = "Wächterin von Tirisfal",
	allegiance = "Orden von Tirisfal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Aegwynn war länger Wächterin von {link:tirisfal-glades}Tirisfal{/link}, als die meisten Königreiche bestanden haben. Der geheime Rat von Tirisfal, gebildet aus den größten Magiern der Länder der {link:humans}Menschen{/link} und der {link:high-elves}Elfen{/link}, erwählte sie zu seiner Streiterin gegen die {link:burning-legion}Brennende Legion{/link} und gab ihr Macht und ein Leben von vielen Jahrhunderten. Man erinnert sich an sie als die mächtigste aller {link:the-night-watch}Wächter{/link} und als diejenige, die den größten Schaden anrichtete, ohne es je zu wollen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[In einem einzigen Sieg versetzte Aegwynn der Legion den schwersten Schlag, den sie auf {link:azeroth}Azeroth{/link} je erlitt. Im selben Augenblick öffnete sie die Tür zu ihrem größten Triumph. Der Dämonenfürst {link:sargeras}Sargeras{/link} verbarg sich in ihr, und durch sie ging er in ihren Sohn {link:medivh}Medivh{/link} über.]=],
		},
		{
			title = "Die Wächterin",
			text = [=[Aegwynn war stolz und furchtlos, und sie wollte nicht die Marionette des Rates sein. Sie jagte Dämonen, wo immer sie wandelten, und sie trug den Mantel viele Menschenleben lang. In {red:northrend}Nordend{/red} fand sie Dämonen, die die letzten Drachen des Nordens jagten und ihnen ihre Magie entzogen. Mit der Hilfe der Drachen vernichtete sie sie. Dann erschien {link:sargeras}Sargeras{/link} selbst in einem gewaltigen Sturm vor ihr. Aegwynn kämpfte gegen seinen Avatar und erschlug ihn. Sie versiegelte seinen zerschmetterten Leib in einer uralten Halle, die bei der {link:great-sundering}Großen Teilung{/link} unter das Meer gesunken war, damit er sich nie wieder erheben könne. Sie glaubte, der Herr der Legion sei besiegt. Sie wusste nicht, dass sein Geist in ihren eigenen geschlüpft war.]=],
		},
		{
			title = "Der Erbe der Wächterin",
			text = [=[In den langen Jahren, die folgten, entfernte sich Aegwynn vom Rat. Sie kam zu der Überzeugung, dass seine Mitglieder sich in die Angelegenheiten von Königen einmischten, und sie beschloss, dass sie niemals den nächsten {link:the-night-watch}Wächter{/link} wählen würden. Sie nahm Nielas Aran, den Beschwörer des Hofes von {link:stormwind-city}Stormwind{/link}, zum Gefährten und gebar ihm einen Sohn. Sie legte die Macht von {link:tirisfal-glades}Tirisfal{/link} in das Kind, auf dass sie erwache, wenn es mündig würde. Dann ließ sie den Knaben bei seinem Vater und zog sich aus der Welt zurück.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie trug den Mantel der Wächterin viele Jahrhunderte lang und vernichtete Dämonen überall in den Östlichen Königreichen.
• Sie verteidigte die Drachen von Nordend gegen die Jäger der Legion.
• Sie erschlug den Avatar von {link:sargeras}Sargeras{/link} und begrub seinen Leib unter dem Meer.
• Sie trotzte dem Rat von {link:tirisfal-glades}Tirisfal{/link} und wählte ihren eigenen Erben.]=],
		},
		{
			title = "Schicksal",
			text = [=[Aegwynn überlebte den Sohn, den sie geschaffen hatte. Als sich das Dunkle Portal öffnete und die {link:horde}Horde{/link} kam, erfuhr die Welt, was ihr Stolz gekostet hatte. {link:medivh}Medivh{/link} fiel in {link:karazhan}Karazhan{/link}, und die Linie der {link:the-night-watch}Wächter{/link} endete mit ihm. Aegwynn selbst ging ins Exil, ihre Macht erschöpft. Unter den Gelehrten von {link:theramore-isle}Theramore{/link} wird geflüstert, dass eine alte Frau von großer Weisheit eine Zeit lang in der Wildnis von {link:kalimdor}Kalimdor{/link} gelebt und Lady {link:jaina-proudmoore}Jaina Proudmoore{/link} beraten habe. Wenige kennen ihren Namen, und die ihn kennen, behalten ihn für sich.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Die Geschichtswerke sagen nicht, wie Aegwynn zuerst erwählt wurde oder wie viele Jahre sie den Mantel insgesamt trug. Dieser Eintrag verzeichnet nur, was gewiss ist.]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Medivh", note = "ihr Sohn" },
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "die sie beraten haben soll" },
	},
})

Translate("deDE", "llane-wrynn", {
	title = "Llane Wrynn",
	subtitle = "König von Stormwind im Ersten Krieg",
	allegiance = "Königreich Stormwind · Haus Wrynn",
	aliases = { "Llane", "König Llane" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Llane Wrynn war König von {link:stormwind-city}Stormwind{/link}, als die {link:horde}Horde{/link} durch das {link:dark-portal}Dunkle Portal{/link} kam. Er war ein stolzer und mutiger Herrscher, der Jugendfreund von {link:medivh}Medivh{/link} und von {link:anduin-lothar}Anduin Lothar{/link} und der Vater von König {link:varian-wrynn}Varian Wrynn{/link}. Er führte sein Volk durch die lange Qual des {link:first-war}Ersten Krieges{/link} und starb in seiner eigenen Burg, als seine Stadt fiel.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Llane war der letzte König des alten {link:stormwind-city}Stormwind{/link}. Sein Tod bedeutete das Ende eines Reiches, das über Generationen allein und stolz bestanden hatte. Aus seinem Untergang ging die {link:alliance}Allianz{/link} hervor, denn die Überlebenden, die er zurückließ, trugen die Warnung vor den {link:orcs}Orcs{/link} nach Norden nach {link:lordaeron}Lordaeron{/link}.]=],
		},
		{
			title = "Jugend",
			text = [=[Llane wuchs in Gesellschaft zweier bemerkenswerter Knaben auf: {link:anduin-lothar}Anduin Lothar{/link}, Erbe einer uralten Blutlinie, und {link:medivh}Medivh{/link}, Sohn des Hofbeschwörers. Die drei waren unzertrennlich. Als Medivh in seinen langen Schlaf fiel, wuchs Llane ohne ihn zum Mann heran, und er freute sich, als sein Freund erwachte. Diese Freundschaft sollte ihn in den kommenden Jahren blind machen.]=],
		},
		{
			title = "Der Erste Krieg",
			text = [=[Als im Schwarzen Fenn seltsame Kreaturen gesichtet wurden, schickte Llane {link:anduin-lothar}Lothar{/link}, um herauszufinden, was sie waren. Es waren {link:orcs}Orcs{/link}, und sie waren nur die ersten. Llane ernannte Lothar zu seinem Streiter und schickte Boten zu den anderen Königreichen der {link:humans}Menschen{/link}, doch wenige glaubten die Geschichte. Jahrelang kämpfte {link:stormwind-city}Stormwind{/link} allein. Dörfer brannten im {link:elwynn-forest}Wald von Elwynn{/link}, in {link:westfall}Westfall{/link} und im {link:redridge-mountains}Rotkammgebirge{/link}. Die {link:horde}Horde{/link} belagerte die {link:capital-city}Hauptstadt{/link} und wurde zurückgeschlagen, denn Lothar fiel ihr überraschend in den Rücken. Als {link:khadgar}Khadgar{/link} und die Halborcin {link:garona}Garona{/link} den König warnten, dass {link:medivh}Medivh{/link} selbst die Eindringlinge gebracht hatte, wollte Llane nicht glauben, dass sein Freund ihn verraten könnte.]=],
		},
		{
			title = "Taten",
			text = [=[• Er ernannte {link:anduin-lothar}Anduin Lothar{/link} zum Streiter des Königreichs und vertraute ihm dessen Verteidigung an.
• Er sandte Warnungen vor den {link:orcs}Orcs{/link} an die anderen Königreiche der {link:humans}Menschen{/link}.
• Er hielt {link:stormwind-city}Stormwind{/link} gegen die erste große Belagerung der {link:horde}Horde{/link}.
• Er zog {link:garona}Garona{/link} nach dem Fall von {link:medivh}Medivh{/link} ins Vertrauen.]=],
		},
		{
			title = "Schicksal",
			text = [=[Nach Medivhs Tod riss der {link:orcs}Orc{/link} {link:orgrim-doomhammer}Orgrim Doomhammer{/link} das Kommando über die {link:horde}Horde{/link} an sich und führte sie erneut gegen {link:stormwind-city}Stormwind{/link}. Die Mauern wurden durchbrochen, doch Llane hielt die Burg. {link:garona}Garona{/link}, die seine vertraute Beraterin geworden war, war noch immer an den Willen der Hexenmeister der Horde gebunden. Sie erschlug den König in seinem Gemach. Der junge Prinz {link:varian-wrynn}Varian{/link} sah seinen Vater sterben. Stormwind fiel, und die Horde machte es dem Erdboden gleich. {link:anduin-lothar}Lothar{/link} sammelte die Überlebenden und führte sie über das Meer nach {link:lordaeron}Lordaeron{/link}. Llanes Königreich ist seither wieder aufgebaut worden, und sein Sohn herrschte auf seinem Thron bis zu seinem jüngsten Verschwinden. Sein Enkel, {link:anduin-wrynn}Anduin Wrynn{/link}, wartet nun in der wiedererbauten Burg, benannt nach dem Streiter, der seine Familie rettete.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Die Chroniken sagen wenig über Llanes Königin oder über die Jahre seiner Herrschaft, bevor sich das Portal öffnete.]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Medivh", note = "sein Jugendfreund" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "sein Streiter" },
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "sein Sohn" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "führte die Horde, die seine Stadt einnahm" },
		{ id = "garona", name = "Garona", note = "seine Beraterin und seine Mörderin" },
	},
})

Translate("deDE", "anduin-lothar", {
	title = "Anduin Lothar",
	subtitle = "Der Löwe von Azeroth",
	allegiance = "Königreich Stormwind · Allianz von Lordaeron",
	aliases = { "Lothar", "Sir Anduin Lothar" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Sir Anduin Lothar war der Streiter von {link:stormwind-city}Stormwind{/link} im {link:first-war}Ersten Krieg{/link} und der erste Oberbefehlshaber der {link:alliance}Allianz{/link} im {link:second-war}Zweiten Krieg{/link}. Er war der letzte bekannte Erbe des königlichen Blutes von {link:arathor}Arathor{/link}, dem uralten Reich, aus dem die Königreiche der Menschen hervorgingen. Die Soldaten nannten ihn den Löwen von {link:azeroth}Azeroth{/link}. Ohne ihn hätten die Nationen der {link:humans}Menschen{/link} vielleicht nie zusammengestanden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Lothar rettete {link:stormwind-city}Stormwind{/link} zweimal: einmal, indem er sein Volk aus der Asche führte, und einmal, indem er die Könige des Nordens überzeugte, dafür zu kämpfen. Die {link:alliance}Allianz{/link}, die er schmiedete, besteht noch immer, und der Enkel seines Königs trägt seinen Namen.]=],
		},
		{
			title = "Der Erste Krieg",
			text = [=[Lothar war der Jugendfreund von {link:llane-wrynn}Llane Wrynn{/link} und {link:medivh}Medivh{/link}. Als im Schwarzen Fenn zuerst {link:orcs}Orcs{/link} gesichtet wurden, schickte der König ihn, um sie auszukundschaften, und er kehrte mit der Nachricht von einem Krieg zurück. Llane machte ihn zum Streiter des Königreichs. Lothar kämpfte jahrelang überall im Reich. Als die {link:horde}Horde{/link} {link:stormwind-city}Stormwind{/link} zum ersten Mal belagerte, führte er die Ritter des Königreichs über das Meer um sie herum und fiel ihr in den Rücken, womit er den Ansturm brach. Mit dem jungen Magier {link:khadgar}Khadgar{/link} erklomm er {link:karazhan}Karazhan{/link} und stellte sich Medivh, seinem ältesten Freund, und dort wurde der {link:the-night-watch}Wächter{/link} erschlagen. Doch das Königreich war nicht zu retten. Als Stormwind fiel, führte Lothar die Überlebenden nach Norden über das Meer.]=],
		},
		{
			title = "Der Zweite Krieg",
			text = [=[In {link:lordaeron}Lordaeron{/link} trat Lothar vor König {link:terenas-menethil}Terenas Menethil{/link} und die Herren der nördlichen Nationen und warnte sie, dass die {link:horde}Horde{/link} als Nächstes zu ihnen kommen werde. Sie hörten ihn an. Die {link:alliance}Allianz von Lordaeron{/link} wurde geboren, und Lothar wurde zu ihrem Befehlshaber ernannt. Die {link:high-elves}Hochelfen{/link} von {link:quel-thalas}Quel'Thalas{/link} schlossen sich ihr an, denn sie schuldeten dem Blut von {link:arathor}Arathor{/link} eine uralte Dankesschuld, und Lothar war sein letzter Erbe. Mit {link:khadgar}Khadgar{/link} und dem jungen Paladin {link:turalyon}Turalyon{/link} als seinen Leutnants bekämpfte er die Horde überall in den nördlichen Königreichen und trieb sie zurück in den Süden.]=],
		},
		{
			title = "Taten",
			text = [=[• Er kundschaftete die ersten {link:orcs}Orcs{/link} im Schwarzen Fenn aus und warnte seinen König.
• Er brach die erste Belagerung von {link:stormwind-city}Stormwind{/link} mit einem Angriff vom Meer aus.
• Er erschlug {link:medivh}Medivh{/link} in {link:karazhan}Karazhan{/link}, mit {link:khadgar}Khadgar{/link} an seiner Seite.
• Er führte das Volk von Stormwind ins Exil nach {link:lordaeron}Lordaeron{/link}.
• Er überzeugte die Königreiche der {link:humans}Menschen{/link}, sich zu vereinen, und befehligte ihre Armeen.]=],
		},
		{
			title = "Schicksal",
			text = [=[Am Ende des Zweiten Krieges verfolgte Lothar die {link:horde}Horde{/link} bis zum {link:blackrock-mountain}Blackrock{/link} in der {link:burning-steppes}Brennenden Steppe{/link}. Dort, in der Schlacht am Fuß des Berges, fiel er durch die Hand von {link:orgrim-doomhammer}Orgrim Doomhammer{/link}. Sein Tod zerbrach die {link:alliance}Allianz{/link} nicht. {link:turalyon}Turalyon{/link} nahm sein Schwert auf, sammelte die trauernden Soldaten und zerschmetterte die Horde. {link:stormwind-city}Stormwind{/link} wurde zurückerobert, und König {link:varian-wrynn}Varian Wrynn{/link} benannte später seinen Sohn Anduin zu Ehren des Streiters.]=],
		},
	},
	bonds = {
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "sein König und Freund" },
		{ id = "medivh", name = "Medivh", note = "Freund und Feind" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "gab ihm den Befehl über die Allianz" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "sein Mörder" },
		{ id = "turalyon", name = "Turalyon", note = "sein Leutnant und Nachfolger" },
		{ id = "anduin-wrynn", name = "Anduin Wrynn", note = "zu seinen Ehren benannt" },
	},
})

Translate("deDE", "tiffin-wrynn", {
	title = "Tiffin Wrynn",
	subtitle = "Königin von Stormwind",
	allegiance = "Königreich Stormwind · Haus Wrynn",
	aliases = { "Tiffin", "Königin Tiffin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tiffin Wrynn war die Königin von König {link:varian-wrynn}Varian Wrynn{/link} und die Mutter von Prinz {link:anduin-wrynn}Anduin Wrynn{/link}. Sie saß in den Jahren nach dem {link:second-war}Zweiten Krieg{/link} an Varians Seite, als sich {link:stormwind-city}Stormwind{/link} wieder aus seiner Asche erhob. Sie erlebte die Vollendung der Stadt nicht mehr. Sie starb im Aufstand der Steinmetze, ein Opfer des Streits zwischen den Adligen der Krone und den Männern, die ihre Mauern wieder aufgebaut hatten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Tiffins Tod ist eine der stillen Wunden des neuen {link:stormwind-city}Stormwind{/link}. Er nahm dem Erben des Königreichs eine Mutter und seinem König eine Frau. Er bezeichnete auch den Augenblick, in dem der Zorn der Steinmetze zu offenem Aufruhr wurde, aus dem die {link:defias-brotherhood}Bruderschaft der Defias{/link} hervorging.]=],
		},
		{
			title = "Der Wiederaufbau",
			text = [=[Nach dem Zweiten Krieg kehrten die Verbannten von {link:stormwind-city}Stormwind{/link} heim und fanden ihre Stadt in Trümmern. Die {link:stonemasons-guild}Steinmetzgilde{/link}, angeführt von {link:edwin-vancleef}Edwin VanCleef{/link}, arbeitete jahrelang daran, sie neu zu errichten. {link:varian-wrynn}Varian{/link}, der Sohn von {link:llane-wrynn}Llane Wrynn{/link}, bestieg den Thron seiner Väter. Tiffin wurde seine Königin, und mit der Zeit gebar sie ihm einen Sohn, Anduin, benannt nach dem Streiter {link:anduin-lothar}Anduin Lothar{/link}. Eine Weile schien es, als könnte das Königreich wieder Frieden kennen.]=],
		},
		{
			title = "Der Aufstand",
			text = [=[Das {link:house-of-nobles}Haus der Adligen{/link} hatte versprochen, die Steinmetze für ihre Arbeit zu bezahlen. Als die Arbeit getan war, weigerten sich die Adligen. Die Steinmetze protestierten in den Straßen der {link:capital-city}Hauptstadt{/link}, und der Protest wurde zum Aufstand. Im Chaos wurde die Königin niedergestreckt und getötet. Die Steinmetze wurden in Schande aus der Stadt vertrieben, und die Verbittertsten unter ihnen flohen nach {link:westfall}Westfall{/link}. Dort legten sie das rote Kopftuch an, und ihre Bruderschaft macht seither Jagd auf das Königreich.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie war Königin von {link:stormwind-city}Stormwind{/link} in den Jahren nach seinem Wiederaufbau.
• Sie gebar {link:varian-wrynn}Varian{/link} einen Sohn und Erben, Anduin.]=],
		},
		{
			title = "Schicksal",
			text = [=[Tiffin ist tot. Ihr Sohn ist noch ein Knabe, und in diesen Tagen wartet er in der {link:stormwind-keep}Burg Stormwind{/link}, während das Schicksal seines Vaters ungewiss bleibt und Hochlord {link:bolvar-fordragon}Bolvar Fordragon{/link} als Regent herrscht. Die Steinmetze, die einst der Krone dienten, führen nun von den Minen und Höfen Westfalls aus ihren eigenen Krieg gegen sie. Viele in {link:stormwind-city}Stormwind{/link} sprechen noch immer mit Liebe von der Königin und mit Scham von ihrem Tod.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Wenig ist über Tiffins Leben geschrieben, bevor sie Königin wurde. Die Chroniken verzeichnen ihre Heirat, ihren Sohn und ihren Tod, und fast nichts von ihren eigenen Worten oder Taten. Dieser Eintrag füllt dieses Schweigen nicht mit Vermutungen.]=],
		},
	},
	bonds = {
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "ihr Gemahl" },
		{ id = "anduin-wrynn", name = "Anduin Wrynn", note = "ihr Sohn" },
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "der Vater ihres Gemahls" },
		{ id = "edwin-vancleef", name = "Edwin VanCleef", note = "führte die Steinmetze, deren Aufstand sie das Leben kostete" },
	},
})

Translate("deDE", "terenas-menethil", {
	title = "Terenas Menethil",
	subtitle = "König von Lordaeron",
	allegiance = "Königreich Lordaeron · Allianz von Lordaeron",
	aliases = { "Terenas", "König Terenas" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[König Terenas Menethil der Zweite herrschte über {link:lordaeron}Lordaeron{/link}, das größte der Königreiche der {link:humans}Menschen{/link} im Norden. In seiner {link:capital-city}Hauptstadt{/link} wurde die {link:alliance}Allianz{/link} gegründet, und unter seinem Banner wurde die {link:horde}Horde{/link} im {link:second-war}Zweiten Krieg{/link} besiegt. Er war der Vater von Prinz {link:arthas-menethil}Arthas Menethil{/link} und von Prinzessin Calia. Er starb durch die Hand seines Sohnes, und sein Königreich starb mit ihm.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Terenas war der Schlussstein der {link:alliance}Allianz von Lordaeron{/link}. Er nahm die Flüchtlinge aus {link:stormwind-city}Stormwind{/link} auf und hörte {link:anduin-lothar}Anduin Lothar{/link} an, als andere Könige es nicht taten. Doch der Frieden, der auf seinen Sieg folgte, zerfaserte unter seiner Herrschaft, und das letzte Schicksal seines Reiches ist das dunkelste in der Geschichte der Menschheit.]=],
		},
		{
			title = "Die Allianz",
			text = [=[Als {link:anduin-lothar}Lothar{/link} die Verbannten von {link:stormwind-city}Stormwind{/link} nach Norden brachte, rief Terenas die Herren der Nationen der {link:humans}Menschen{/link} in seine {link:capital-city}Hauptstadt{/link}. {link:gilneas}Gilneas{/link}, {link:kul-tiras}Kul Tiras{/link}, {link:stromgarde-keep}Stromgarde{/link}, {link:alterac-mountains}Alterac{/link} und {link:dalaran}Dalaran{/link} schickten ihre Herrscher und Gesandten, und die {link:high-elves}Hochelfen{/link} von {link:quel-thalas}Quel'Thalas{/link} schlossen sich ihnen später an. Terenas gab Lothar den Befehl über die vereinten Armeen. Lordaerons eigene Länder litten schwer im Krieg, doch am Ende wurde die {link:horde}Horde{/link} zerschlagen, und ihre {link:orcs}Orcs{/link} wurden gefangen genommen.]=],
		},
		{
			title = "Der zerfasernde Frieden",
			text = [=[Nach dem Krieg befahl Terenas, die gefangenen {link:orcs}Orcs{/link} in großen Internierungslagern festzuhalten. Die Lager waren kostspielig, und er besteuerte die anderen Nationen, um sie zu bezahlen. Streit erwuchs über die Lager und über das Schicksal des verräterischen Königreichs {link:alterac-mountains}Alterac{/link}. Eines nach dem anderen zogen sich {link:gilneas}Gilneas{/link}, {link:stromgarde-keep}Stromgarde{/link} und {link:quel-thalas}Quel'Thalas{/link} aus der {link:alliance}Allianz{/link} zurück. Als sich eine seltsame Seuche in den nördlichen Ackerländern von {link:lordaeron}Lordaeron{/link} auszubreiten begann, schickte der König seinen Sohn {link:arthas-menethil}Arthas{/link} und den Paladin {link:uther-the-lightbringer}Uther den Lichtbringer{/link}, um ihr ein Ende zu setzen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er hieß die Flüchtlinge aus {link:stormwind-city}Stormwind{/link} in seinem Königreich willkommen.
• Er gründete die {link:alliance}Allianz von Lordaeron{/link} und gab {link:anduin-lothar}Anduin Lothar{/link} ihren Befehl.
• Er befahl nach dem Zweiten Krieg den Bau der {link:internment-camps}Internierungslager{/link}.
• Er schickte {link:arthas-menethil}Arthas{/link} und {link:uther-the-lightbringer}Uther{/link} gegen die Seuche im Norden.]=],
		},
		{
			title = "Schicksal",
			text = [=[{link:arthas-menethil}Arthas{/link} kehrte als Held aus {red:northrend}Nordend{/red} heim, und das Volk der {link:capital-city}Hauptstadt{/link} streute Blütenblätter auf seinen Weg. Der Prinz schritt in den Thronsaal, kniete vor seinem Vater nieder und erschlug ihn dann mit der Runenklinge {red:frostmourne}Frostgram{/red}. Mit dem Tod des Königs fiel das Königreich an die {link:scourge}Geißel{/link}. {link:uther-the-lightbringer}Uther{/link} trug später die Asche des Königs in einer Urne in Richtung {link:quel-thalas}Quel'Thalas{/link}, doch Arthas streckte den Paladin nieder und schüttete die Asche aus. Die Hauptstadt von Terenas liegt in Trümmern, und unter ihr haben die {link:forsaken}Verlassenen{/link} von Lady {link:sylvanas-windrunner}Sylvanas Windrunner{/link} {link:undercity}Undercity{/link} erbaut.]=],
		},
	},
	bonds = {
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "sein Sohn und sein Mörder" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "Befehlshaber seiner Allianz" },
		{ id = "uther-the-lightbringer", name = "Uther der Lichtbringer", note = "sein treuer Paladin" },
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "Erzbischof seines Glaubens" },
	},
})

Translate("deDE", "arthas-menethil", {
	title = "Arthas Menethil",
	subtitle = "Der gefallene Prinz",
	allegiance = [=[Geißel (einst Königreich Lordaeron, Ritter der Silbernen Hand)]=],
	aliases = { "Arthas", "Prinz Arthas" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Arthas Menethil war der Kronprinz von {link:lordaeron}Lordaeron{/link}, ein Ritter der Silbernen Hand und der Schüler von {link:uther-the-lightbringer}Uther dem Lichtbringer{/link}. Er war tapfer, geliebt und stolz. Er zog aus, um sein Volk vor einer Seuche des Untodes zu retten, und am Ende vernichtete er es. Er ermordete seinen Vater, König {link:terenas-menethil}Terenas Menethil{/link}, und führte die {link:scourge}Geißel{/link} über den Norden. Nun beherrscht er die Untoten aus dem gefrorenen Herzen von {red:northrend}Nordend{/red}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Kein Fall in der Geschichte der Menschheit war so groß oder so schrecklich. Der Name Arthas ist in jedem Land verflucht, das einst die {link:alliance}Allianz{/link} kannte, und die Länder, die er verwüstete, heißen noch immer die Pestländer.]=],
		},
		{
			title = "Der Prinz",
			text = [=[Arthas war der einzige Sohn von {link:terenas-menethil}Terenas{/link}. {link:uther-the-lightbringer}Uther{/link} bildete ihn zum Paladin des {link:holy-light}Heiligen Lichts{/link} aus, und er wurde in den Orden der Silbernen Hand aufgenommen. Als eine Seuche die nördlichen Ackerländer von {link:lordaeron}Lordaeron{/link} heimsuchte, schickte der König Arthas und Uther, um ihr ein Ende zu setzen. Mit {link:jaina-proudmoore}Jaina Proudmoore{/link} aus {link:dalaran}Dalaran{/link} an seiner Seite folgte Arthas der Krankheit bis zum Nekromanten {link:kel-thuzad}Kel'Thuzad{/link} und seinem {link:cult-of-the-damned}Kult der Verdammten{/link} und erschlug ihn. Doch die Seuche breitete sich weiter aus. In Stratholme fand Arthas heraus, dass das Getreide der Stadt verseucht war und dass alle, die davon gegessen hatten, als Untote auferstehen würden. Er befahl, die Stadt zu säubern. Uther und Jaina weigerten sich, daran teilzunehmen, und Arthas vollzog {link:culling-of-stratholme}das Ausmerzen von Stratholme{/link} ohne sie.]=],
		},
		{
			title = "Der Fall",
			text = [=[Arthas verfolgte den Schreckenslord Mal'Ganis nach Nordend. Dort verbrannte er seine eigenen Schiffe, damit seine Männer nicht umkehren konnten, und er nahm die verfluchte Runenklinge {red:frostmourne}Frostgram{/red} auf. Mit ihr erschlug er Mal'Ganis, doch das Schwert forderte seine Seele. Er kehrte als Diener des {red:lich-king}Lichkönigs{/red} nach {link:lordaeron}Lordaeron{/link} heim. Im Thronsaal ermordete er seinen Vater, und das Königreich fiel. Er vernichtete den Orden der Silbernen Hand, erschlug {link:uther-the-lightbringer}Uther{/link} und erweckte {link:kel-thuzad}Kel'Thuzad{/link} neben dem Sonnenbrunnen wieder, nachdem er {link:quel-thalas}Quel'Thalas{/link} verwüstet hatte. Er tötete die Waldläufergeneralin {link:sylvanas-windrunner}Sylvanas Windrunner{/link} und band ihren Geist an seinen Willen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er vollzog das Ausmerzen von Stratholme.
• Er ermordete {link:terenas-menethil}König Terenas{/link} und übergab {link:lordaeron}Lordaeron{/link} der {link:scourge}Geißel{/link}.
• Er erschlug {link:uther-the-lightbringer}Uther{/link} den Lichtbringer.
• Er verheerte {link:quel-thalas}Quel'Thalas{/link} und entweihte den Sonnenbrunnen, um {link:kel-thuzad}Kel'Thuzad{/link} als Lich zu erwecken.
• Er öffnete der {link:burning-legion}Brennenden Legion{/link} den Weg nach {link:dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Schicksal",
			text = [=[Nach der {link:battle-of-mount-hyjal}Schlacht um den Berg Hyjal{/link} schwand die Macht des Lichkönigs, und Arthas verlor seinen Griff um {link:lordaeron}Lordaeron{/link}. {link:sylvanas-windrunner}Sylvanas{/link} befreite sich von seiner Herrschaft, und die {link:forsaken}Verlassenen{/link} erhoben sich gegen ihn. Von seinem Herrn gerufen, kehrte Arthas nach Nordend zurück. Am Gletscher der Eiskrone kämpfte er gegen {link:illidan-stormrage}Illidan Stormrage{/link} und besiegte ihn. Dann erklomm er den Frostthron und setzte den Helm des Lichkönigs auf, und die beiden wurden eins. Arthas herrscht nun als Lichkönig in Nordend. In Lordaeron befehligt {link:kel-thuzad}Kel'Thuzad{/link} die {link:scourge}Geißel{/link} in seinem Namen. {link:muradin-bronzebeard}Muradin Bronzebeard{/link}, der ihm einst nach Norden folgte, kehrte nie heim.]=],
		},
	},
	bonds = {
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "sein Vater und sein Opfer" },
		{ id = "uther-the-lightbringer", name = "Uther der Lichtbringer", note = "sein Lehrer und sein Opfer" },
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "seine verlorene Liebe" },
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "Feind, dann Diener" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "der Lichkönig, mit dem er eins wurde" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "Feind an der Eiskrone" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "sein Opfer und seine Feindin" },
	},
})

Translate("deDE", "uther-the-lightbringer", {
	title = "Uther der Lichtbringer",
	subtitle = "Erster der Paladine",
	allegiance = "Ritter der Silbernen Hand · Kirche des Heiligen Lichts",
	aliases = { "Uther", "Lord Uther" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Uther der Lichtbringer war der erste Paladin des {link:holy-light}Heiligen Lichts{/link} und der Anführer der Ritter der Silbernen Hand. Er lernte seinen Glauben an der Seite von Erzbischof {link:alonsus-faol}Alonsus Faol{/link}, bekämpfte die {link:horde}Horde{/link} im {link:second-war}Zweiten Krieg{/link} überall im Norden und bildete den Prinzen {link:arthas-menethil}Arthas Menethil{/link} aus. Er war der Lehrer und Freund des Prinzen, und er starb durch die Hand des Prinzen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Uther zeigte den Königreichen der {link:humans}Menschen{/link}, dass Glaube und Stahl zusammenstehen können. Der Orden, den er führte, verteidigte {link:lordaeron}Lordaeron{/link} eine Generation lang, und sein Name wird von jedem Paladin der Welt noch immer mit Ehrfurcht ausgesprochen.]=],
		},
		{
			title = "Die Silberne Hand",
			text = [=[Nach dem {link:first-war}Ersten Krieg{/link} drang die Kunde nach Norden, dass die {link:horde}Horde{/link} die Geistlichen der {link:northshire-abbey}Abtei von Nordhain{/link} niedergemetzelt hatte. {link:alonsus-faol}Alonsus Faol{/link} beschloss, dass die Diener des Lichts nicht länger wehrlos dastehen sollten. Mit dem Segen von {link:anduin-lothar}Anduin Lothar{/link} sammelte er Krieger von starkem Glauben und lehrte sie, heilige Macht im Kampf zu führen. Uther war der Erste unter ihnen. Als ihre Ausbildung vollendet war, ernannte ihn der Erzbischof zum Anführer der neuen Ritter der Silbernen Hand. Uther und seine Paladine, unter ihnen {link:turalyon}Turalyon{/link} und {link:tirion-fordring}Tirion Fordring{/link}, kämpften den ganzen Zweiten Krieg hindurch und brachten Heilung und Hoffnung dorthin, wo die Kämpfe am schlimmsten waren.]=],
		},
		{
			title = "Der Prinz",
			text = [=[In den Jahren des Friedens nahm Uther den jungen {link:arthas-menethil}Arthas{/link} als Schüler an und hieß ihn im Orden willkommen. Als im Norden von {link:lordaeron}Lordaeron{/link} eine Seuche ausbrach, schickte König {link:terenas-menethil}Terenas Menethil{/link} sie beide, um ihr ein Ende zu setzen. In Stratholme befahl Arthas, das Volk der Stadt zu töten, bevor die Seuche es erwecken konnte. Uther weigerte sich. Er wollte die Lebenden nicht niederstrecken, und Arthas entließ ihn aus seinem Dienst. {link:culling-of-stratholme}Das Ausmerzen von Stratholme{/link} ging ohne ihn weiter.]=],
		},
		{
			title = "Taten",
			text = [=[• Er war der erste von {link:alonsus-faol}Alonsus Faol{/link} geweihte Paladin und führte die Ritter der Silbernen Hand.
• Er bekämpfte die {link:horde}Horde{/link} im Zweiten Krieg.
• Er bildete {link:arthas-menethil}Prinz Arthas{/link} in den Wegen des Lichts aus.
• Er weigerte sich, am Ausmerzen von Stratholme teilzunehmen.]=],
		},
		{
			title = "Schicksal",
			text = [=[Als {link:arthas-menethil}Arthas{/link} aus {red:northrend}Nordend{/red} zurückkehrte und seinen Vater ermordete, wandte sich der Prinz gegen den Orden, der ihn großgezogen hatte. Er zerschlug die Silberne Hand und jagte ihre Ritter. Uther und seine letzten Paladine bewachten die Urne, die die Asche von {link:terenas-menethil}König Terenas{/link} enthielt. Arthas kam, um sie zu holen, und der Schüler erschlug seinen Lehrer mit der Runenklinge {red:frostmourne}Frostgram{/red}. Ein {link:the-sepulcher}Grabmal{/link} steht nun zu Uthers Gedenken in den {link:western-plaguelands}Westlichen Pestländern{/link}, ein Ort der Trauer in einem toten Land. Einige der Paladine, die er ausbildete, leben noch, und sie erinnern sich an ihn.]=],
		},
	},
	bonds = {
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "sein Mentor" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "sein Schüler und sein Mörder" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "sein König" },
		{ id = "turalyon", name = "Turalyon", note = "ein Bruder der Silbernen Hand" },
		{ id = "tirion-fordring", name = "Tirion Fordring", note = "ein Bruder der Silbernen Hand" },
	},
})

Translate("deDE", "alonsus-faol", {
	title = "Alonsus Faol",
	subtitle = "Erzbischof des Heiligen Lichts",
	allegiance = "Kirche des Heiligen Lichts · Ritter der Silbernen Hand",
	aliases = { "Erzbischof Faol", "Erzbischof Alonsus Faol" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Alonsus Faol war der Erzbischof der Kirche des {link:holy-light}Heiligen Lichts{/link}, der geistliche Vater der Königreiche der {link:humans}Menschen{/link} im Zeitalter des {link:second-war}Zweiten Krieges{/link}. Er war ein kleiner, stämmiger alter Mann mit weißem Bart und gütigem Gesicht, geliebt von einfachen Leuten und Königen gleichermaßen. Er gründete die Ritter der Silbernen Hand und weihte {link:uther-the-lightbringer}Uther den Lichtbringer{/link} als ersten der Paladine.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Vor Faol heilten und beteten die Diener des Lichts, während andere kämpften. Nach ihm ritten sie in den Krieg. Die Paladinorden aller Länder der {link:humans}Menschen{/link} und die jungen Paladine, die heute in der {link:northshire-abbey}Abtei von Nordhain{/link} ausgebildet werden, gehen alle den Weg, den er eröffnete.]=],
		},
		{
			title = "Die Silberne Hand",
			text = [=[Faol hatte dem Glauben lange gedient, und er nahm den jungen {link:uther-the-lightbringer}Uther{/link} viele Jahre, bevor die {link:orcs}Orcs{/link} kamen, als Lehrling an. Während des {link:first-war}Ersten Krieges{/link} brannte die {link:horde}Horde{/link} die {link:northshire-abbey}Abtei von Nordhain{/link} nieder und metzelte ihre Geistlichen nieder. Als die Überlebenden von {link:stormwind-city}Stormwind{/link} {link:lordaeron}Lordaeron{/link} erreichten, hörte der Erzbischof von dem Gemetzel, und er beschloss, dass es nicht wieder geschehen sollte. Gemeinsam mit {link:anduin-lothar}Anduin Lothar{/link} gründete er einen Orden heiliger Krieger. Er wählte Ritter von starkem Glauben und lehrte sie, das Licht im Kampf anzurufen. Uther, {link:turalyon}Turalyon{/link}, {link:tirion-fordring}Tirion Fordring{/link} und einige andere waren die ersten. Als ihre Ausbildung vollendet war, ernannte Faol Uther zum Anführer der Ritter der Silbernen Hand.]=],
		},
		{
			title = "Der Frieden",
			text = [=[Faol war zugegen, als sich die Herren der Nationen der {link:humans}Menschen{/link} in der {link:capital-city}Hauptstadt{/link} von {link:lordaeron}Lordaeron{/link} trafen. Es heißt, er habe geholfen, ihre Gemüter zu kühlen, wenn ihre Streitigkeiten hitzig wurden. Nach dem Krieg wandte er seine Sorge dem Wiederaufbau des Südens zu. Er schickte seine Priester und Paladine, wo immer sie gebraucht wurden, und er unterstützte die Errichtung der neuen {link:cathedral-of-light}Kathedrale des Lichts{/link} in {link:stormwind-city}Stormwind{/link} und die Wiederherstellung von {link:northshire-abbey}Nordhain{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bildete {link:uther-the-lightbringer}Uther{/link} im Glauben an das Licht aus.
• Er gründete mit {link:anduin-lothar}Anduin Lothar{/link} die Ritter der Silbernen Hand.
• Er weihte die ersten Paladine und ernannte Uther zu ihrem Anführer.
• Er beriet die Herren der {link:alliance}Allianz{/link} während des Zweiten Krieges.
• Er half beim Wiederaufbau von {link:stormwind-city}Stormwind{/link} und der {link:northshire-abbey}Abtei von Nordhain{/link}.]=],
		},
		{
			title = "Schicksal",
			text = [=[Faol starb in den Jahren nach dem Zweiten Krieg. Die Chroniken sagen nicht, wie. Sein Schüler {link:archbishop-benedictus}Benedictus{/link} folgte ihm als Erzbischof nach und hütet noch immer die {link:cathedral-of-light}Kathedrale des Lichts{/link} in {link:stormwind-city}Stormwind{/link}. Faol wurde in {link:tirisfal-glades}Tirisfal{/link} zur Ruhe gebettet, in einem {link:the-sepulcher}Grabmal{/link} namens Faols Ruheplatz. Dieses Land gehört nun den Untoten, und die {link:forsaken}Verlassenen{/link} wandeln, wo einst die Gläubigen zum Beten kamen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik erzählt, wie oder wann Alonsus Faol starb. Auch verzeichnet sie wenig von seinem Leben, bevor er Erzbischof wurde.]=],
		},
	},
	bonds = {
		{ id = "uther-the-lightbringer", name = "Uther der Lichtbringer", note = "sein Lehrling" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "gründete mit ihm die Silberne Hand" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "sein König in Lordaeron" },
	},
})

Translate("deDE", "orgrim-doomhammer", {
	title = "Orgrim Doomhammer",
	subtitle = "Kriegshäuptling der Horde im Zweiten Krieg",
	aliases = { "Orgrim", "Kriegshäuptling Doomhammer" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Orgrim Doomhammer war der Kriegshäuptling der {link:horde}Horde{/link}, der {link:stormwind-city}Stormwind{/link} eroberte und die {link:orcs}Orcs{/link} im {link:second-war}Zweiten Krieg{/link} anführte. Er war ein Krieger des Blackrockklans, der Träger des großen Hammers seiner Familie und der älteste Freund von Durotan vom {link:frostwolf-clan}Frostwolfklan{/link}. Er hasste die Hexenmeister, die sein Volk verdorben hatten, und er versuchte auf seine Weise, es zu befreien. Am Ende seines Lebens fand er den Orc, der dieses Werk vollenden sollte: {link:thrall}Thrall{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Doomhammer machte die {link:horde}Horde{/link} zu einer einzigen Armee mit einem einzigen Willen. Unter ihm kam sie der Eroberung der Königreiche der {link:humans}Menschen{/link} näher als je zuvor. Doch sein größtes Vermächtnis ist keine Eroberung. Es ist die neue Horde, und ihre {link:capital-city}Hauptstadt{/link} {link:orgrimmar}Orgrimmar{/link} trägt seinen Namen.]=],
		},
		{
			title = "Der Erste Krieg",
			text = [=[In den frühen Jahren des Krieges diente Orgrim als Stellvertreter des Kriegshäuptlings Blackhand, einer Marionette des Hexenmeisters {link:gul-dan}Gul'dan{/link}. Als Durotan von Gul'dans Meuchelmördern ermordet wurde, ließ sich Orgrims Zorn nicht länger zügeln. Nach dem Tod von {link:medivh}Medivh{/link} forderte er Blackhand zu einem Zweikampf auf Leben und Tod heraus und zertrümmerte ihm mit dem Doomhammer den Schädel. Als Kriegshäuptling verbot er die dunkle Magie, die Draenor vergiftet hatte. Er führte die {link:horde}Horde{/link} erneut gegen {link:stormwind-city}Stormwind{/link}, und diesmal fiel die Stadt. Dann fand er das Versteck des Schattenrats der Hexenmeister und metzelte die meisten von ihnen nieder.]=],
		},
		{
			title = "Der Zweite Krieg",
			text = [=[Doomhammer verschonte {link:gul-dan}Gul'dan{/link}, der ihm neue Waffen versprach. Er rief die volle Stärke der {link:horde}Horde{/link} auf und marschierte nach Norden. Er nahm die {link:kingdom-of-ironforge}Zwergenlande{/link} von Khaz Modan ein, verbündete sich mit den Waldtrollen der Amani und setzte die roten Drachen des Dragonmawklans im Kampf ein. Seine Armeen verbrannten die Wälder von {link:quel-thalas}Quel'Thalas{/link} und belagerten die {link:capital-city}Hauptstadt{/link} von {link:lordaeron}Lordaeron{/link}. Dann verriet ihn Gul'dan und führte einen großen Teil der Horde fort. Die Belagerung scheiterte. Am {link:blackrock-mountain}Blackrock{/link} erschlug Doomhammer {link:anduin-lothar}Anduin Lothar{/link} im Kampf, doch der Paladin {link:turalyon}Turalyon{/link} sammelte die {link:alliance}Allianz{/link}, und die Horde wurde zerschmettert.]=],
		},
		{
			title = "Taten",
			text = [=[• Er erschlug Blackhand und machte sich selbst zum Kriegshäuptling.
• Er eroberte {link:stormwind-city}Stormwind{/link} und beendete den {link:first-war}Ersten Krieg{/link}.
• Er vernichtete den {link:shadow-council}Schattenrat{/link}.
• Er führte die {link:horde}Horde{/link} bis vor die Tore der {link:capital-city}Hauptstadt{/link} von {link:lordaeron}Lordaeron{/link}.
• Er erschlug {link:anduin-lothar}Anduin Lothar{/link} am {link:blackrock-mountain}Blackrock{/link}.]=],
		},
		{
			title = "Schicksal",
			text = [=[Doomhammer wurde gefangen genommen und in Ketten in der {link:capital-city}Hauptstadt{/link} von {link:lordaeron}Lordaeron{/link} zur Schau gestellt. Er entkam und lebte viele Jahre im Verborgenen. Als der junge {link:thrall}Thrall{/link}, der Sohn Durotans, ihn aufsuchte, erkannte ihn der alte Kriegshäuptling sofort. Er schloss sich Thrall an, um die {link:orcs}Orcs{/link} aus den Internierungslagern zu befreien, und er fiel in einer dieser Schlachten in den Hügeln des {link:hillsbrad-foothills}Vorgebirges von Hillsbrad{/link}. Bevor er starb, ernannte er Thrall zum neuen Kriegshäuptling. Thrall trägt nun Doomhammers schwarze Rüstung und seinen Hammer in {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "sein Erbe als Kriegshäuptling" },
		{ id = "gul-dan", name = "Gul'dan", note = "der Hexenmeister, den er verachtete" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "der Feind, den er erschlug" },
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "der König, dessen Stadt er einnahm" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "ein Häuptling wie er" },
	},
})

Translate("deDE", "grom-hellscream", {
	title = "Grom Hellscream",
	subtitle = "Häuptling der Warsong",
	aliases = { "Grommash", "Grommash Hellscream" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Grom Hellscream war der Häuptling des Warsongklans, der wildeste der Kriegsherren der {link:orcs}Orcs{/link} und der treueste Freund von {link:thrall}Thrall{/link}. Er war der erste Orc, der das Blut des Dämons {link:mannoroth}Mannoroth{/link} trank, und so band er sein Volk an die {link:burning-legion}Brennende Legion{/link}. Er war auch der Orc, der diese Bindung brach, um den Preis seines eigenen Lebens.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Der Fluch der {link:orcs}Orcs{/link} begann mit Grom und endete mit ihm. Sein Tod im {link:ashenvale}Eschental{/link} befreite die Orcs vom Dämonenblut, und die {link:horde}Horde{/link} von heute verdankt ihre Freiheit seinem letzten Kampf.]=],
		},
		{
			title = "Der Blutfluch",
			text = [=[Auf {red:draenor}Draenor{/red} versammelte der Hexenmeister {link:gul-dan}Gul'dan{/link} die Häuptlinge der Clans und bot ihnen einen Trank aus Mannoroths Blut an. Grom trank als Erster, und die anderen folgten. Das Blut erfüllte die {link:orcs}Orcs{/link} mit einer schrecklichen Wut und band sie an den Willen der Legion. Als die {link:horde}Horde{/link} gegen {link:azeroth}Azeroth{/link} zog, sorgte Gul'dan dafür, dass Grom und seine Warsong auf Draenor blieben. Sie verpassten den {link:second-war}Zweiten Krieg{/link} ganz. Nach dem Krieg kamen sie durch das {link:dark-portal}Dunkle Portal{/link} und kämpften darum, bis es zerstört wurde, und sie blieben gestrandet in den Ländern der {link:humans}Menschen{/link} zurück.]=],
		},
		{
			title = "Die Lethargie",
			text = [=[Viele Jahre lang lebten die Warsong verborgen in der Wildnis von {link:lordaeron}Lordaeron{/link}. Wie alle {link:orcs}Orcs{/link} war Grom krank vom Verlust der dämonischen Raserei. Doch er bekämpfte die Lethargie mit eisernem Willen. Als der junge {link:thrall}Thrall{/link} ihn aufsuchte, sah Grom in ihm die Hoffnung seines Volkes. Er schloss sich Thrall an, um die Orcs aus den Internierungslagern zu befreien. Am Vorabend des {link:third-war}Dritten Krieges{/link} wurde er von den {link:humans}Menschen{/link} gefangen genommen, und Thrall befreite ihn erneut.]=],
		},
		{
			title = "Kalimdor",
			text = [=[Die {link:orcs}Orcs{/link} segelten westwärts nach {link:kalimdor}Kalimdor{/link}. Dort wurden die Warsong in die Wälder des Eschentals geschickt, um Holz zu schlagen, und sie gerieten mit den {link:night-elves}Nachtelfen{/link} aneinander. Der Halbgott {link:cenarius}Cenarius{/link} kam, um den Wald zu verteidigen. Verzweifelt nach einem Sieg tranken Grom und seine Krieger aus einer Quelle, die {link:mannoroth}Mannoroth{/link} mit seinem Blut verunreinigt hatte. Der alte Fluch kehrte zurück. In dieser Raserei erschlug Grom Cenarius. {link:thrall}Thrall{/link}, unterstützt von {link:jaina-proudmoore}Jaina Proudmoore{/link}, nahm seinen Freund gefangen und reinigte ihn von der Wut.]=],
		},
		{
			title = "Taten",
			text = [=[• Er war der erste {link:orcs}Orc{/link}, der das Blut von {link:mannoroth}Mannoroth{/link} trank.
• Er hielt nach dem Zweiten Krieg das Dunkle Portal gegen die {link:alliance}Allianz{/link}.
• Er widerstand der Lethargie der Orcs durch Jahre des Verbergens.
• Er half {link:thrall}Thrall{/link}, die Orcs aus den {link:camping}Lagern{/link} zu befreien.
• Er erschlug {link:cenarius}Cenarius{/link}, dann erschlug er Mannoroth.]=],
		},
		{
			title = "Schicksal",
			text = [=[Grom und {link:thrall}Thrall{/link} gingen gemeinsam zu der Schlucht, in der {link:mannoroth}Mannoroth{/link} wartete. Thrall erlag der Macht des Dämons. Grom stürmte allein vor, trieb seine Axt in Mannoroths Brust und erschlug ihn. Der Tod des Dämons befreite die {link:orcs}Orcs{/link} vom Blutfluch. Grom starb an seinen Wunden in Thralls Armen. Sein Clan schlägt noch immer im Namen der {link:horde}Horde{/link} die Bäume des Eschentals, und die {link:night-elves}Nachtelfen{/link} bekämpfen ihn noch immer um jeden Baum.]=],
		},
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "sein Kriegshäuptling und Freund" },
		{ id = "gul-dan", name = "Gul'dan", note = "gab ihm das Blut des Dämons" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "ein Häuptling wie er" },
		{ id = "archimonde", name = "Archimonde", note = "der Herr des Dämons, den er erschlug" },
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "half, ihn zu befreien" },
	},
})

Translate("deDE", "gul-dan", {
	title = "Gul'dan",
	subtitle = "Der Verräter der Orcs",
	allegiance = "Schattenrat · Stormreaverklan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gul'dan war der erste Hexenmeister der {link:orcs}Orcs{/link} und der Baumeister der alten {link:horde}Horde{/link}. Er war einst der Lehrling des Schamanen {link:ner-zhul}Ner'zhul{/link}. Er verkaufte sein Volk für Macht an die {link:burning-legion}Brennende Legion{/link}, und er vergiftete sowohl sein Volk als auch seine Welt. Er öffnete das {link:dark-portal}Dunkle Portal{/link} mit {link:medivh}Medivh{/link} und führte die verborgenen Herren der Horde, den {link:shadow-council}Schattenrat{/link}. Am Ende verriet er die Horde selbst.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Viel vom Leid der {link:orcs}Orcs{/link} und der Völker, die sie bekämpften, lässt sich auf Gul'dans Ehrgeiz zurückführen. Seine {link:fel-magic}Teufelsmagie{/link} entzog {red:draenor}Draenor{/red} das Leben. Sein Dämonenblut machte die Orcs zu Sklaven ihrer Wut. Sein Verrat kostete die {link:horde}Horde{/link} den {link:second-war}Zweiten Krieg{/link}.]=],
		},
		{
			title = "Der Schattenrat",
			text = [=[Auf Draenor suchte der Dämonenfürst {link:kil-jaeden}Kil'jaeden{/link} einen Diener unter den {link:orcs}Orcs{/link}. Als {link:ner-zhul}Ner'zhul{/link} an dem Dämon zu zweifeln begann, wandte sich Kil'jaeden an Gul'dan, der überhaupt keine Zweifel hatte. Kil'jaeden lehrte ihn die Künste der Teufelszauberei. Gul'dan gründete den {link:shadow-council}Schattenrat{/link}, einen Kreis von Hexenmeistern, der die Clans hinter einem Marionettenhäuptling, Blackhand, beherrschte. Er bot den Häuptlingen das Blut von {link:mannoroth}Mannoroth{/link} an, und sie tranken. Dann erreichte ihn eine Stimme aus einer anderen Welt. Es war {link:medivh}Medivh{/link}, und gemeinsam öffneten sie das Dunkle Portal nach {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Die Kriege",
			text = [=[Am Ende des {link:first-war}Ersten Krieges{/link} versuchte Gul'dan, Medivhs sterbendem Geist die Geheimnisse des Grabmals von {link:sargeras}Sargeras{/link} zu entreißen. Der Versuch warf ihn in eine lange Starre. Während er schlief, tötete {link:orgrim-doomhammer}Orgrim Doomhammer{/link} Blackhand und vernichtete den größten Teil des Schattenrats. Als Gul'dan erwachte, erkaufte er sich sein Leben mit dem Versprechen neuer Waffen. Er und seine Hexenmeister erweckten die ersten Todesritter der {link:horde}Horde{/link}. Doch seine Treue war eine Maske. Als Doomhammer die {link:capital-city}Hauptstadt{/link} von {link:lordaeron}Lordaeron{/link} belagerte, nahm Gul'dan seine Anhänger und segelte davon, um das {link:the-sepulcher}Grabmal{/link} von Sargeras unter dem Meer zu suchen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er gründete den {link:shadow-council}Schattenrat{/link} und beherrschte die {link:horde}Horde{/link} durch Blackhand.
• Er gab den Häuptlingen das Blut von {link:mannoroth}Mannoroth{/link}.
• Er öffnete das Dunkle Portal mit {link:medivh}Medivh{/link}.
• Er erweckte die ersten Todesritter der Horde.
• Er ließ Doomhammer vor den Toren der {link:capital-city}Hauptstadt{/link} von {link:lordaeron}Lordaeron{/link} im Stich.]=],
		},
		{
			title = "Schicksal",
			text = [=[Gul'dan hob das {link:the-sepulcher}Grabmal{/link} von {link:sargeras}Sargeras{/link} aus den Tiefen des Großen Meeres empor und betrat es in der Hoffnung, die Macht eines Gottes zu erlangen. Die Dämonen, die es bewachten, rissen ihn in Stücke. Doomhammers Krieger, ausgesandt, um seinen Verrat zu bestrafen, metzelten seine Anhänger nieder. Ohne sie konnte die {link:horde}Horde{/link} die Belagerung nicht halten, und sie wurde in die Niederlage zurückgetrieben. Gul'dans Schädel überdauerte ihn, und er trug eine eigene dunkle Macht in sich, bis er im {link:third-war}Dritten Krieg{/link} zerstört wurde.]=],
		},
	},
	bonds = {
		{ id = "ner-zhul", name = "Ner'zhul", note = "sein erster Meister" },
		{ id = "medivh", name = "Medivh", note = "öffnete mit ihm das Dunkle Portal" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "der Kriegshäuptling, den er verriet" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "trank als Erster sein Blut" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "nahm die Macht seines Schädels" },
	},
})

Translate("deDE", "ner-zhul", {
	title = "Ner'zhul",
	subtitle = "Ältester Schamane der Shadowmoon",
	allegiance = "Shadowmoonklan · Geißel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ner'zhul war der älteste Schamane des Shadowmoonklans und der angesehenste geistige Führer der {link:orcs}Orcs{/link} von {red:draenor}Draenor{/red}. Der Dämonenfürst {link:kil-jaeden}Kil'jaeden{/link} täuschte ihn und benutzte ihn, um die Orcs gegen die Draenei aufzubringen. Später riss Ner'zhul seine eigene Welt auseinander, bei dem Versuch, aus ihr zu fliehen. Von den Dämonen gefangen, wurde er zum {red:lich-king}Lichkönig{/red} gemacht, dem Herrn der {link:scourge}Geißel{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ner'zhul brachte zweimal Verderben. Als Schamane öffnete er die Herzen seines Volkes für die {link:burning-legion}Brennende Legion{/link}. Als Lichkönig sandte er eine Seuche des Untodes über {link:lordaeron}Lordaeron{/link}. Der {link:third-war}Dritte Krieg{/link} und die toten Länder des Nordens sind ebenso sein Werk wie das irgendeines anderen.]=],
		},
		{
			title = "Der Getäuschte",
			text = [=[In den alten Tagen Draenors lebten die {link:orcs}Orcs{/link} als Clans von Jägern und Schamanen. Ner'zhul sprach unter ihnen für die Geister. Dann kam {link:kil-jaeden}Kil'jaeden{/link} zu ihm, verkleidet als Geist der Ahnen, und flüsterte ihm zu, dass die friedlichen Draenei gegen die Orcs Ränke schmiedeten. Ner'zhul glaubte ihm und führte sein Volk in den Krieg. Erst später erkannte er die Wahrheit, und als er sich weigerte, weiterzugehen, wandte sich Kil'jaeden stattdessen an seinen Lehrling, {link:gul-dan}Gul'dan{/link}. Ner'zhul wurde beiseitegeschoben und lebte in Schande, während die {link:horde}Horde{/link} nach {link:azeroth}Azeroth{/link} marschierte.]=],
		},
		{
			title = "Die Zerschmetterung",
			text = [=[Nach dem {link:second-war}Zweiten Krieg{/link} scharten sich die {link:orcs}Orcs{/link}, die auf Draenor geblieben waren, um den alten Schamanen. Er öffnete das {link:dark-portal}Dunkle Portal{/link} erneut und schickte Krieger, um mächtige Relikte von {link:azeroth}Azeroth{/link} zu stehlen, denn er wollte seinem Volk Tore zu neuen Welten öffnen. Die {link:alliance}Allianz{/link} schickte eine Expedition durch das Portal, um ihn aufzuhalten. Ner'zhul öffnete seine Tore dennoch. Die Energien rissen Draenor auseinander, und er floh mit seinen Anhängern durch einen Riss.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führte die {link:orcs}Orcs{/link} als ihr größter Schamane.
• Er führte die Clans unter Kil'jaedens Täuschung gegen die Draenei.
• Er öffnete das Dunkle Portal nach dem Zweiten Krieg erneut.
• Er zerschmetterte Draenor mit seinen Toren.
• Als Lichkönig erweckte er die {link:scourge}Geißel{/link} und entfesselte die Seuche über {link:lordaeron}Lordaeron{/link}.]=],
		},
		{
			title = "Schicksal",
			text = [=[{link:kil-jaeden}Kil'jaeden{/link} wartete jenseits des Risses auf ihn. Der Dämon riss dem Schamanen das Fleisch vom Leib und band seinen Geist in eine Rüstung und einen Helm. Er versiegelte Ner'zhul in einem Eisblock und schleuderte ihn nach {link:azeroth}Azeroth{/link}. Er fiel auf den Gletscher der Eiskrone in {red:northrend}Nordend{/red}, und dort wurde er zum Lichkönig. Vom Frostthron aus erweckte er die {link:scourge}Geißel{/link}. Er rief {link:kel-thuzad}Kel'Thuzad{/link} in seinen Dienst und sandte die Seuche nach Süden. Schließlich nahm er den Prinzen {link:arthas-menethil}Arthas Menethil{/link} durch die Runenklinge {red:frostmourne}Frostgram{/red} in Besitz. Als seine Macht schwand, rief er Arthas zur Eiskrone, und der Prinz setzte seinen Helm auf. Ner'zhul und Arthas sind nun eins, und der Lichkönig herrscht im Norden.]=],
		},
	},
	bonds = {
		{ id = "gul-dan", name = "Gul'dan", note = "sein Lehrling und sein Usurpator" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "der Prinz, den er in Besitz nahm und mit dem er eins wurde" },
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "sein Diener" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "Häuptling seiner Horde" },
	},
})

Translate("deDE", "archimonde", {
	title = "Archimonde",
	subtitle = "Der Entweiher",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Archimonde {link:razelikh-the-defiler}der Entweiher{/link} war einer der großen Fürsten der {link:burning-legion}Brennenden Legion{/link}, nur ihrem dunklen Herrn {link:sargeras}Sargeras{/link} untergeordnet. Er war einst ein Anführer der Eredar, eines stolzen Volkes einer anderen Welt, bis Sargeras ihnen Macht anbot und er annahm. Er führte die Kriege der Legion über unzählige Welten. Auf {link:azeroth}Azeroth{/link} kam er näher als jeder Dämon vor ihm daran, die Welt zu verschlingen, und er starb am Fuß des Weltenbaums.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Archimondes Invasion im {link:third-war}Dritten Krieg{/link} war der größte dämonische Angriff, den die Welt seit dem {link:war-of-the-ancients}Krieg der Ahnen{/link} erlebt hatte. Seine Niederlage am {link:mount-hyjal}Berg Hyjal{/link} schmiedete einen unruhigen Frieden zwischen {link:orcs}Orcs{/link}, {link:humans}Menschen{/link} und {link:night-elves}Nachtelfen{/link}, einen Frieden, der {link:kalimdor}Kalimdor{/link} seither geprägt hat.]=],
		},
		{
			title = "Die Eredar",
			text = [=[Vor langer Zeit wurden die Eredar von drei Anführern beherrscht: Archimonde, {link:kil-jaeden}Kil'jaeden{/link} und Velen. {link:sargeras}Sargeras{/link} kam mit einem Angebot von Wissen und Macht zu ihnen. Archimonde und Kil'jaeden nahmen an, und sie wurden zu Dämonen verzerrt. Velen lehnte ab und floh mit seinen Anhängern. Archimonde wurde einer der größten Leutnants von Sargeras. Im {link:war-of-the-ancients}Krieg der Ahnen{/link}, vor zehntausend Jahren, kam die Legion durch den {link:well-of-eternity}Brunnen der Ewigkeit{/link} nach {link:azeroth}Azeroth{/link}. Sie wurde zurückgetrieben, als der Brunnen zerstört wurde.]=],
		},
		{
			title = "Der Dritte Krieg",
			text = [=[Die Legion kehrte viele Zeitalter später zurück. Als die {link:scourge}Geißel{/link} {link:lordaeron}Lordaeron{/link} verwüstet hatte, benutzte der Lich {link:kel-thuzad}Kel'Thuzad{/link} das Zauberbuch von {link:medivh}Medivh{/link}, um Archimonde in die Stadt {link:dalaran}Dalaran{/link} zu beschwören. Der Dämonenfürst zerstörte {link:city-of-dalaran}die Stadt der Magier{/link} mit einem einzigen Schlag seiner Macht. Dann führte er die Legion nach {link:kalimdor}Kalimdor{/link}, wo die letzten Wasser des {link:well-of-eternity}Brunnens der Ewigkeit{/link} unter dem Weltenbaum {link:nordrassil}Nordrassil{/link} lagen. Er wollte seine Macht aussaugen und die Welt verzehren.]=],
		},
		{
			title = "Taten",
			text = [=[• Er nahm das Angebot von {link:sargeras}Sargeras{/link} an und wurde ein Fürst der Legion.
• Er führte im {link:war-of-the-ancients}Krieg der Ahnen{/link} Krieg gegen {link:azeroth}Azeroth{/link}.
• Er wurde von {link:kel-thuzad}Kel'Thuzad{/link} nach {link:dalaran}Dalaran{/link} beschworen und zerstörte es.
• Er marschierte auf den {link:mount-hyjal}Berg Hyjal{/link}, um die Macht von {link:nordrassil}Nordrassil{/link} auszusaugen.]=],
		},
		{
			title = "Schicksal",
			text = [=[In der {link:battle-of-mount-hyjal}Schlacht um den Berg Hyjal{/link} hielten die {link:orcs}Orcs{/link} von {link:thrall}Thrall{/link}, die {link:humans}Menschen{/link} von {link:jaina-proudmoore}Jaina Proudmoore{/link} und die {link:night-elves}Nachtelfen{/link} von {link:tyrande-whisperwind}Tyrande Whisperwind{/link} und {link:malfurion-stormrage}Malfurion Stormrage{/link} die Hänge des Berges, so lange sie konnten. Archimonde erklomm schließlich den Weltenbaum. Malfurion blies das Horn des {link:cenarius}Cenarius{/link}, und ein gewaltiges Heer von Geistern der Ahnen umschwärmte den Dämonenfürsten und vernichtete ihn in einer gewaltigen Explosion. Die Macht von {link:nordrassil}Nordrassil{/link} war erschöpft, und die Nachtelfen verloren ihre Unsterblichkeit. Doch die Invasion der Legion war gebrochen. Ihre Dämonen verweilen noch in den verderbten Wäldern des {link:felwood}Teufelswalds{/link}, und ihr Schatten hat die Welt nicht verlassen.]=],
		},
	},
	bonds = {
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "beschwor ihn nach Azeroth" },
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "führte seine Vernichtung herbei" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "Feind im Dritten Krieg" },
		{ id = "queen-azshara", name = "Königin Azshara", note = "die der Legion einst den Weg öffnete" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "erschlug seinen Diener Mannoroth" },
	},
})

Translate("deDE", "illidan-stormrage", {
	title = "Illidan Stormrage",
	subtitle = "Der Verräter",
	allegiance = "Unbekannt (einst der Widerstand der Kaldorei)",
	aliases = { "Illidan", "Illidan der Verräter" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Illidan Stormrage war ein Zauberer der {link:night-elves}Nachtelfen{/link} aus der alten Welt, der Zwillingsbruder von {link:malfurion-stormrage}Malfurion Stormrage{/link} und ein Rivale um die Liebe von {link:tyrande-whisperwind}Tyrande Whisperwind{/link}. Er bekämpfte die {link:burning-legion}Brennende Legion{/link}, und er diente ihr auch. Er war zehntausend Jahre lang eingekerkert und wurde im {link:third-war}Dritten Krieg{/link} befreit. Manche nennen ihn einen Helden, und viele nennen ihn einen Verräter. Sein eigenes Volk nannte ihn den Verräter.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Illidans Entscheidungen haben die Welt in gleichem Maße gerettet und bedroht. In alter Zeit trug er die Wasser des {link:well-of-eternity}Brunnens der Ewigkeit{/link} zum {link:mount-hyjal}Berg Hyjal{/link}, wo sie noch immer unter {link:nordrassil}Nordrassil{/link} liegen. Im Dritten Krieg erschlug er einen Fürsten der Legion und nahm dessen Macht für sich.]=],
		},
		{
			title = "Der Krieg der Ahnen",
			text = [=[Illidan wurde mit bernsteinfarbenen Augen geboren, einem Zeichen, das Größe verheißen sollte. Er fühlte sich zur {link:arcane-magic}arkanen Magie{/link} hingezogen, wie sein Bruder zum Pfad des {link:cenarius}Cenarius{/link}. Im {link:war-of-the-ancients}Krieg der Ahnen{/link} kämpfte er an der Seite der {link:night-elves}Nachtelfen{/link} gegen {link:queen-azshara}Königin Azshara{/link} und ihre dämonischen Verbündeten. Doch er wurde eifersüchtig auf seinen Bruder und hungrig nach Macht, und schließlich ging er zu {link:sargeras}Sargeras{/link} selbst. Der Dämonenfürst brannte ihm die Augen aus und gab ihm eine neue Sicht. Als der {link:well-of-eternity}Brunnen der Ewigkeit{/link} zerstört wurde, goss Illidan gestohlene Phiolen seines Wassers in einen See auf dem Gipfel des Berges Hyjal und schuf so einen neuen Brunnen. {link:malfurion-stormrage}Malfurion{/link} hielt dies für ein Verbrechen. Er ließ seinen Bruder unter der Erde anketten, bewacht von der Wärterin Maiev Shadowsong.]=],
		},
		{
			title = "Der Dritte Krieg",
			text = [=[Zehntausend Jahre später kamen die {link:scourge}Geißel{/link} und die Legion nach {link:kalimdor}Kalimdor{/link}. Gegen das Gesetz ihres Volkes befreite {link:tyrande-whisperwind}Tyrande{/link} Illidan, damit er helfe. In dem Wald, den man heute {link:felwood}Teufelswald{/link} nennt, verzehrte er den Schädel von {link:gul-dan}Gul'dan{/link}, nahm die Gestalt eines Dämons an und erschlug den Schreckenslord {link:tichondrius}Tichondrius{/link}. {link:malfurion-stormrage}Malfurion{/link} verbannte ihn aus den Wäldern der {link:night-elves}Nachtelfen{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er kämpfte im {link:war-of-the-ancients}Krieg der Ahnen{/link} gegen {link:azshara}Azshara{/link}.
• Er schuf einen neuen {link:well-of-eternity}Brunnen der Ewigkeit{/link} auf dem Gipfel des Berges Hyjal.
• Er verzehrte den {link:skull-of-gul-dan}Schädel von Gul'dan{/link} und erschlug {link:tichondrius}Tichondrius{/link}.
• Er rief nach dem Dritten Krieg die {link:naga}Naga{/link} der Tiefe in seinen Dienst.]=],
		},
		{
			title = "Schicksal",
			text = [=[Nach seiner Verbannung sammelte Illidan die {link:naga}Naga{/link} und suchte das {link:the-sepulcher}Grabmal{/link} von {link:sargeras}Sargeras{/link} unter dem Meer. Er wurde von Maiev verfolgt, und von seinem Bruder und {link:tyrande-whisperwind}Tyrande{/link}, und er entkam ihnen allen. Später marschierte er nach {red:northrend}Nordend{/red}, um den {red:lich-king}Lichkönig{/red} zu treffen. Am Gletscher der Eiskrone kämpfte er gegen {link:arthas-menethil}Arthas Menethil{/link} und wurde besiegt. Er floh mit seinen überlebenden Anhängern. Wohin er danach ging, kann keine Chronik der Königreiche sagen.]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "sein Zwillingsbruder" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "die Liebe, die er verlor" },
		{ id = "queen-azshara", name = "Königin Azshara", note = "Feindin aus alter Zeit" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "besiegte ihn an der Eiskrone" },
		{ id = "gul-dan", name = "Gul'dan", note = "dessen Schädel er verzehrte" },
	},
})

Translate("deDE", "malfurion-stormrage", {
	title = "Malfurion Stormrage",
	subtitle = "Der erste Druide",
	allegiance = "Nachtelfen · Zirkel des Cenarius",
	aliases = { "Malfurion" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Malfurion Stormrage war der erste Druide der {link:night-elves}Nachtelfen{/link}, der Schüler des Halbgottes {link:cenarius}Cenarius{/link} und der Zwillingsbruder von {link:illidan-stormrage}Illidan Stormrage{/link}. Er führte den Kampf gegen die {link:burning-legion}Brennende Legion{/link} im {link:war-of-the-ancients}Krieg der Ahnen{/link} und erneut im {link:third-war}Dritten Krieg{/link}. Er ist der Geliebte von {link:tyrande-whisperwind}Tyrande Whisperwind{/link}. Nun schläft er im {link:emerald-dream}Smaragdgrünen Traum{/link}, und sein Volk wartet darauf, dass er erwacht.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Malfurion rettete die Welt zweimal. In alter Zeit zerstörte er den {link:well-of-eternity}Brunnen der Ewigkeit{/link}, um der Legion die Tür zu verschließen. Zehntausend Jahre später vernichtete er {link:archimonde}Archimonde{/link} am Fuß des Weltenbaums. Die Druiden aller Länder folgen dem Pfad, den er als Erster ging.]=],
		},
		{
			title = "Der Krieg der Ahnen",
			text = [=[Malfurion fühlte sich zur lebendigen Welt hingezogen, während sein Bruder das Arkane studierte. {link:cenarius}Cenarius{/link} nahm ihn als Schüler an und lehrte ihn, die Mächte der Natur zu formen. Als {link:queen-azshara}Königin Azshara{/link} und ihre Hochgeborenen die Legion in die Welt brachten, schloss sich Malfurion dem Widerstand an. Er sah, dass die Legion nur aufzuhalten war, indem man den {link:well-of-eternity}Brunnen der Ewigkeit{/link} selbst zerstörte. Sein Angriff darauf setzte die {link:great-sundering}Große Teilung{/link} in Gang, die das Land zerschmetterte und die {link:capital-city}Hauptstadt{/link} der Königin ertränkte. Als {link:illidan-stormrage}Illidan{/link} auf dem {link:mount-hyjal}Berg Hyjal{/link} einen neuen Brunnen schuf, ließ Malfurion ihn einkerkern. Mit der Hilfe der großen Drachen pflanzten die Überlebenden {link:nordrassil}Nordrassil{/link} auf dem neuen Brunnen. Malfurion und seine Druiden fielen dann in einen langen Schlaf im Smaragdgrünen Traum.]=],
		},
		{
			title = "Der Dritte Krieg",
			text = [=[Als die Legion zurückkehrte, weckte {link:tyrande-whisperwind}Tyrande{/link} die Druiden. Malfurion führte sie zurück in die Welt und half, die Wälder des {link:ashenvale}Eschentals{/link} gegen die Dämonen zu halten. Gegen seinen Willen befreite Tyrande {link:illidan-stormrage}Illidan{/link}, und er kam zu spät, um seinen Bruder daran zu hindern, die Macht eines Dämons an sich zu nehmen. Er verbannte Illidan und kehrte zur Verteidigung des Hyjal zurück. Dort stand er mit den {link:orcs}Orcs{/link} von {link:thrall}Thrall{/link} und den {link:humans}Menschen{/link} von {link:jaina-proudmoore}Jaina Proudmoore{/link}. Als {link:archimonde}Archimonde{/link} {link:nordrassil}Nordrassil{/link} erreichte, blies Malfurion das Horn des {link:cenarius}Cenarius{/link}. Die Geister der Ahnen vernichteten den Dämonenfürsten, und die Welt war gerettet.]=],
		},
		{
			title = "Taten",
			text = [=[• Er lernte die Wege der Natur von {link:cenarius}Cenarius{/link} und wurde der erste Druide.
• Er zerstörte den {link:well-of-eternity}Brunnen der Ewigkeit{/link} und beendete den {link:war-of-the-ancients}Krieg der Ahnen{/link}.
• Er kerkerte seinen Bruder unter der Erde ein.
• Er führte die Druiden im Dritten Krieg gegen die Legion.
• Er vernichtete {link:archimonde}Archimonde{/link} in der Schlacht um den {link:mount-hyjal}Berg Hyjal{/link}.]=],
		},
		{
			title = "Schicksal",
			text = [=[Nach dem Krieg jagte Malfurion {link:illidan-stormrage}Illidan{/link} über das Meer und ließ ihn dann ziehen. Er kehrte in den Smaragdgrünen Traum zurück und ist seither nicht erwacht. In seiner Abwesenheit führt Erzdruide {link:fandral-staghelm}Fandral Staghelm{/link} die Druiden von {link:darnassus}Darnassus{/link}, und die {link:night-elves}Nachtelfen{/link} haben einen neuen Weltenbaum gepflanzt, {link:teldrassil}Teldrassil{/link}. {link:tyrande-whisperwind}Tyrande{/link} herrscht und wartet.]=],
		},
	},
	bonds = {
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "sein Zwillingsbruder" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "seine Geliebte" },
		{ id = "archimonde", name = "Archimonde", note = "der Dämon, den er vernichtete" },
		{ id = "queen-azshara", name = "Königin Azshara", note = "die Königin, die er bekämpfte" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "führt an seiner Stelle die Druiden" },
	},
})

Translate("deDE", "queen-azshara", {
	title = "Königin Azshara",
	subtitle = "Königin der Hochgeborenen",
	allegiance = "Hochgeborene · Naga",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Königin Azshara herrschte über das alte Reich der {link:night-elves}Nachtelfen{/link} auf dem Höhepunkt seines Ruhmes. Sie war die schönste und mächtigste ihres Volkes, und es betete sie an. Von ihrem Palast in Zin-Azshari neben dem {link:well-of-eternity}Brunnen der Ewigkeit{/link} aus führte sie die Hochgeborenen im Studium der {link:arcane-magic}arkanen Magie{/link}. In ihrem Stolz öffnete sie die Welt für die {link:burning-legion}Brennende Legion{/link}, und ihr Reich ertrank unter dem Meer.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Azsharas Verrat begann den {link:war-of-the-ancients}Krieg der Ahnen{/link} und endete in der {link:great-sundering}Großen Teilung{/link}. Die zerbrochene Gestalt von {link:kalimdor}Kalimdor{/link} und den {link:eastern-kingdoms}Östlichen Königreichen{/link} ist ihr Vermächtnis. Ebenso vielleicht die {link:naga}Naga{/link}, die sich nun aus den Wellen erheben.]=],
		},
		{
			title = "Die Königin der Hochgeborenen",
			text = [=[Azsharas Volk benannte Städte und Berge nach ihr. Die Hochgeborenen, die edle Kaste ihres Hofes, dienten ihr als Priester und Zauberer. Unter ihrer Herrschaft schöpften sie immer tiefer aus dem {link:well-of-eternity}Brunnen der Ewigkeit{/link}. Ihre Zauber reichten über die Welt hinaus und zogen den Blick von {link:sargeras}Sargeras{/link} auf sich. Der Dämonenfürst flüsterte der Königin zu, und sie hörte zu. Sie kam zu der Überzeugung, dass die Welt von allen geringeren Völkern gereinigt werden sollte und dass Sargeras dies vollbringen würde.]=],
		},
		{
			title = "Der Krieg der Ahnen",
			text = [=[{link:azshara}Azshara{/link} und ihre Hochgeborenen öffneten ein Portal im Brunnen, und die Dämonen der Legion strömten hindurch. Ihr Berater Xavius diente ihr bei diesem Werk. Die {link:night-elves}Nachtelfen{/link}, die frei blieben, erhoben sich gegen ihre Königin, angeführt von {link:malfurion-stormrage}Malfurion Stormrage{/link}, {link:tyrande-whisperwind}Tyrande Whisperwind{/link} und Lord Kur'talos Ravencrest. Während der Krieg tobte, arbeiteten die Hochgeborenen daran, {link:sargeras}Sargeras{/link} selbst in die Welt zu bringen. Sie wurden erst aufgehalten, als der Brunnen zerstört wurde. Sein Zusammenbruch riss das Land auseinander, und das Meer strömte über Zin-Azshari.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie herrschte über die {link:night-elves}Nachtelfen{/link} auf dem Höhepunkt ihrer Macht.
• Sie führte die Hochgeborenen im Gebrauch des Brunnens der Ewigkeit.
• Sie öffnete der Brennenden Legion den Weg nach {link:azeroth}Azeroth{/link}.
• Sie suchte {link:sargeras}Sargeras{/link} selbst in die Welt zu bringen.]=],
		},
		{
			title = "Schicksal",
			text = [=[Als der Brunnen zusammenbrach, verschwanden Azshara und ihre Hochgeborenen unter den Wellen. Die Legenden der {link:night-elves}Nachtelfen{/link} sagen, dass sie nicht starben, sondern verwandelt wurden, und dass die schlangengleichen {link:naga}Naga{/link} das sind, was aus ihnen wurde. Die Naga sind in diesen Tagen an die Ufer zurückgekehrt und überfallen die Küsten von {link:kalimdor}Kalimdor{/link} und anderer Länder. Manche von ihnen sprechen von ihrer uralten Königin, als lebte sie noch. Nur die Ruinen ihres Reiches bleiben in dem Land, das ihren Namen trägt, {link:azshara}Azshara{/link}.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine sterbliche Aufzeichnung sagt, ob {link:azshara}Azshara{/link} unter dem Meer noch lebt oder was aus ihr geworden ist.]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "führte die Rebellion gegen sie an" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "bekämpfte ihren Hof" },
		{ id = "archimonde", name = "Archimonde", note = "ein Fürst der Legion, der sie diente" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "führte die Rebellion gegen sie an" },
	},
})

Translate("deDE", "deathwing", {
	title = "Todesschwinge",
	subtitle = "Der Zerstörer",
	allegiance = "Schwarzer Drachenschwarm",
	aliases = { "Neltharion" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Todesschwinge war einst Neltharion, der Erdwächter, Aspekt des schwarzen Drachenschwarms. Ihm war aufgetragen, die tiefen Orte der Welt zu hüten. Wahnsinn ergriff ihn, und er verriet die anderen Drachenschwärme im {link:war-of-the-ancients}Krieg der Ahnen{/link}. Seitdem hat er gegen jedes Volk von {link:azeroth}Azeroth{/link} Ränke geschmiedet. Sein Name bedeutet Verderben für Drachen und Sterbliche gleichermaßen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Todesschwinges Verrat vernichtete die Drachenschwärme beinahe. Sein Einmischen im {link:second-war}Zweiten Krieg{/link} gab der {link:horde}Horde{/link} ihre Drachen. Seine schwarze Brut sucht noch immer den {link:blackrock-mountain}Blackrock{/link} und andere finstere Orte der Welt heim.]=],
		},
		{
			title = "Der Erdwächter",
			text = [=[In den alten Tagen wurden fünf große Drachen als Aspekte erwählt, um die Welt zu hüten. Neltharion erhielt die Herrschaft über die Erde und ihre Tiefen. Etwas flüsterte ihm tief unter dem Stein zu, und mit der Zeit wandte sich sein Geist. Im {link:war-of-the-ancients}Krieg der Ahnen{/link} schmiedete er eine große Scheibe aus Gold, die Drachenseele. Er überredete die anderen Aspekte, ihr einen Teil ihrer Macht zu geben, und sagte ihnen, sie werde die {link:burning-legion}Brennende Legion{/link} zurücktreiben. Stattdessen wandte er sie gegen sie. Die Macht des Artefakts war so groß, dass sein Leib zu zerreißen begann, und Metallplatten wurden an seiner Haut befestigt, um ihn zusammenzuhalten. Er floh, und die Drachenseele ging verloren.]=],
		},
		{
			title = "Der Zweite Krieg",
			text = [=[Todesschwinge wandelt seit Langem in menschlicher Verkleidung unter den Sterblichen, als Edelmann, der sich durch die Höfe der Könige bewegt. Die Geschichtswerke sagen, er habe Zwietracht gesät, wo immer er konnte. Im Zweiten Krieg fiel die Drachenseele in die Hände der {link:orcs}Orcs{/link} des Dragonmawklans. Mit ihr nahmen sie {link:alexstrasza}Alexstrasza{/link}, den Aspekt der roten Drachen, gefangen und hielten sie unter {link:grim-batol}Grim Batol{/link} fest. Ihre Jungen wurden als Kriegsreittiere für die {link:horde}Horde{/link} aufgezogen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er verriet die Aspekte im {link:war-of-the-ancients}Krieg der Ahnen{/link} mit der Drachenseele.
• Er bewegte sich im Geheimen an den Höfen der {link:humans}Menschen{/link}.
• Er ließ die Drachenseele dem {link:dragonmaw-clan}Dragonmawklan{/link} in die Hände fallen.
• Er versuchte, die Eier des roten Drachenschwarms aus {link:grim-batol}Grim Batol{/link} zu stehlen.]=],
		},
		{
			title = "Schicksal",
			text = [=[Nach dem Zweiten Krieg hielt der {link:dragonmaw-clan}Dragonmawklan{/link} {link:alexstrasza}Alexstrasza{/link} noch immer in {link:grim-batol}Grim Batol{/link} gefangen. Todesschwinge kam wegen ihrer Eier, um seinen eigenen Schwarm wieder aufzubauen. Eine kleine Schar von Helden und Drachen befreite die rote Königin, und die Drachenseele wurde zerstört. Todesschwinge wurde voller Wut vertrieben. Wohin er ging, weiß niemand. Der Berg Grim Batol im {link:wetlands}Sumpfland{/link} wird von den Zwergen bis heute gemieden. Seine Kinder und sein schwarzer Drachenschwarm sind noch immer in der Welt unterwegs.]=],
		},
	},
	bonds = {
		{ id = "alexstrasza", name = "Alexstrasza", note = "der Aspekt, den er versklaven half" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "Kriegshäuptling der Horde, die sein Geschenk nutzte" },
		{ id = "queen-azshara", name = "Königin Azshara", note = "Verbündete der Legion, die er zu bekämpfen vorgab" },
	},
})

Translate("deDE", "kel-thuzad", {
	title = "Kel'Thuzad",
	subtitle = "Gründer des Kults der Verdammten",
	allegiance = "Geißel · Kult der Verdammten (einst Kirin Tor)",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kel'Thuzad war einst ein Erzmagier von {link:dalaran}Dalaran{/link} und ein Mitglied des herrschenden Rates der {link:kirin-tor}Kirin Tor{/link}. Er wandte sich der verbotenen Kunst der Nekromantie zu, verschwor sich dem {red:lich-king}Lichkönig{/red} und gründete den {link:cult-of-the-damned}Kult der Verdammten{/link}. Er verbreitete die Seuche, die {link:lordaeron}Lordaeron{/link} vernichtete. Von Prinz {link:arthas-menethil}Arthas Menethil{/link} erschlagen, erhob er sich erneut als Lich. Nun befehligt er die {link:scourge}Geißel{/link} in Lordaeron im Namen seines Herrn.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ohne Kel'Thuzad hätte die Seuche des Untodes das Volk von {link:lordaeron}Lordaeron{/link} vielleicht nie erreicht. Er war die Stimme des Lichkönigs unter den Lebenden, und er öffnete der {link:burning-legion}Brennenden Legion{/link} den Weg zurück nach {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Der Erzmagier",
			text = [=[Kel'Thuzad war einer der größten Magier von {link:dalaran}Dalaran{/link}, doch er hielt seine Mitmagier für zu zaghaft in ihren Studien. Er begann, sich in die dunkle Kunst der Nekromantie zu vertiefen. Als {link:shadow-council}der Rat{/link} sie verbot, hörte er nicht auf. Eine Stimme rief ihn aus {red:northrend}Nordend{/red}. Er antwortete ihr, reiste in den gefrorenen Norden und verschwor sich dem Lichkönig. Sein Herr versprach ihm ewiges Leben.]=],
		},
		{
			title = "Der Kult der Verdammten",
			text = [=[Kel'Thuzad kehrte nach {link:lordaeron}Lordaeron{/link} zurück und sprach zu den Armen und Müden von einer neuen Gesellschaft, in der alle gleich wären und niemand stürbe. Tausende schlossen sich seinem {link:cult-of-the-damned}Kult der Verdammten{/link} an. Durch sie verseuchte er das Getreide der nördlichen Kornspeicher mit einer Seuche, die die Lebenden in Untote verwandelte. Als {link:arthas-menethil}Arthas{/link} nach Norden kam, um die Seuche zu bekämpfen, fand er Kel'Thuzad in {link:ruins-of-andorhal}Andorhal{/link} und erschlug ihn. Doch der Geist des Nekromanten blieb, und er flüsterte dem Prinzen zu, als dieser fiel.]=],
		},
		{
			title = "Taten",
			text = [=[• Er studierte Nekromantie, den {link:kirin-tor}Kirin Tor{/link} zum Trotz.
• Er verschwor sich in Nordend dem Lichkönig.
• Er gründete den {link:cult-of-the-damned}Kult der Verdammten{/link}.
• Er verbreitete die Seuche des Untodes durch das Getreide von {link:lordaeron}Lordaeron{/link}.
• Er beschwor {link:archimonde}Archimonde{/link} nach {link:dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Schicksal",
			text = [=[Als {link:arthas-menethil}Arthas{/link} ein Diener des Lichkönigs wurde, trug er die Überreste des Nekromanten nach {link:quel-thalas}Quel'Thalas{/link}. Dort, in den Wassern des Sonnenbrunnens, wurde Kel'Thuzad als Lich wiedergeboren. Mit dem Zauberbuch von {link:medivh}Medivh{/link} beschwor er {link:archimonde}Archimonde{/link} nach {link:dalaran}Dalaran{/link}, und der Dämonenfürst legte die Stadt in Trümmer. Als Arthas nach Nordend zurückkehrte, blieb Kel'Thuzad zurück, um die {link:scourge}Geißel{/link} in {link:lordaeron}Lordaeron{/link} zu beherrschen. Das tut er noch immer. Die große Nekropole {red:naxxramas}Naxxramas{/red} schwebt über den Pestländern, und seine Kultisten unterhalten ihre Schule der dunklen Gelehrsamkeit in der alten Burg von {link:caer-darrow}Caer Darrow{/link}.]=],
		},
	},
	bonds = {
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "sein Mörder, dann sein Herr" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "der Lichkönig, dem er sich verschwor" },
		{ id = "archimonde", name = "Archimonde", note = "der Dämon, den er beschwor" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "dessen Asche Platz für seine Gebeine machte" },
	},
})

Translate("deDE", "jaina-proudmoore", {
	title = "Jaina Proudmoore",
	subtitle = "Herrscherin von Theramore",
	found = [=[Foothold-Zitadelle, Insel Theramore, in den Marschen von Dustwallow]=],
	hint = "Sucht die Herrin von Theramore im Turm ihrer Inselzitadelle.",
	allegiance = "Theramore · Allianz · Kirin Tor",
	aliases = { "Jaina", "Lady Jaina Proudmoore", "Lady Proudmoore" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lady Jaina Proudmoore herrscht über {link:theramore-isle}Theramore{/link}, die Inselfestung der {link:alliance}Allianz{/link} an der Ostküste von {link:kalimdor}Kalimdor{/link}. Sie ist die Tochter des Lordadmirals {link:daelin-proudmoore}Daelin Proudmoore{/link} von {link:kul-tiras}Kul Tiras{/link} und eine Zauberin, die in {link:dalaran}Dalaran{/link} von den {link:kirin-tor}Kirin Tor{/link} ausgebildet wurde. Sie ging in den Tagen der Seuche an der Seite von Prinz {link:arthas-menethil}Arthas Menethil{/link}, und sie trennte sich von ihm vor seinem Fall. Sie führte die Überlebenden des Nordens über das Meer, und sie schloss einen Frieden mit der {link:horde}Horde{/link}, den vor ihr niemand für möglich gehalten hatte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Jaina ist die Brücke zwischen den alten Feinden. Sie stand mit {link:thrall}Thrall{/link} in der {link:battle-of-mount-hyjal}Schlacht um den Berg Hyjal{/link}, und sie hält ihm noch immer die Treue. Dieser Frieden kostete sie ihren Vater. Er ist zerbrechlich, und viele auf beiden Seiten sähen ihn gern gebrochen.]=],
		},
		{
			title = "Die Seuche",
			text = [=[Als junge Frau studierte Jaina in {link:dalaran}Dalaran{/link} Magie unter dem Erzmagier Antonidas, und sie zeigte seltene Gaben. Als sich eine seltsame Seuche in den nördlichen Ackerländern von {link:lordaeron}Lordaeron{/link} ausbreitete, ging sie mit {link:arthas-menethil}Prinz Arthas{/link}, um ihre Quelle zu finden. Gemeinsam deckten sie den {link:cult-of-the-damned}Kult der Verdammten{/link} und das verseuchte Getreide auf. In Stratholme befahl Arthas, das Volk der Stadt zu töten, bevor es als Untote auferstehen konnte. Jaina wollte nicht daran teilnehmen, und sie verließ ihn dort. {link:culling-of-stratholme}Das Ausmerzen von Stratholme{/link} ging ohne sie weiter.]=],
		},
		{
			title = "Die Reise nach Westen",
			text = [=[Ein geheimnisvoller Prophet drängte die Anführer des Ostens, westwärts über das Meer zu segeln. Jaina hörte auf ihn, als andere es nicht taten, und sie führte die Überlebenden von {link:lordaeron}Lordaeron{/link} nach {link:kalimdor}Kalimdor{/link}. Dort traf sie {link:thrall}Thrall{/link} und seine {link:orcs}Orcs{/link}, die alten Feinde ihres Volkes. Der Prophet vereinte sie gegen einen größeren Feind, und am {link:mount-hyjal}Berg Hyjal{/link} kämpften Mensch, Orc und {link:night-elves}Nachtelf{/link} Seite an Seite, bis {link:archimonde}Archimonde{/link} vernichtet war.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie studierte Magie bei den {link:kirin-tor}Kirin Tor{/link} von {link:dalaran}Dalaran{/link}.
• Sie jagte die Seuche mit {link:arthas-menethil}Arthas{/link} und verweigerte sich dem Ausmerzen von Stratholme.
• Sie führte die Überlebenden von {link:lordaeron}Lordaeron{/link} westwärts nach {link:kalimdor}Kalimdor{/link}.
• Sie kämpfte am {link:mount-hyjal}Berg Hyjal{/link} an der Seite von {link:thrall}Thrall{/link} und den {link:night-elves}Nachtelfen{/link}.
• Sie gründete {link:theramore-isle}Theramore{/link} und schloss Frieden mit der {link:horde}Horde{/link}.]=],
		},
		{
			title = "Theramore",
			text = [=[Nach dem Krieg errichtete Jaina {link:theramore-isle}Theramore{/link} auf einer Insel vor der Küste der {link:dustwallow-marsh}Marschen von Dustwallow{/link}. Dann kam ihr Vater mit einer großen Flotte nach {link:kalimdor}Kalimdor{/link}. {link:daelin-proudmoore}Daelin{/link} wollte keinen Frieden mit den {link:orcs}Orcs{/link} hinnehmen, und er führte Krieg gegen sie. Jaina konnte ihn nicht dazu bewegen, aufzuhören. Sie wollte nicht zulassen, dass er den Frieden zerstörte, und sie hielt sich abseits, während die {link:horde}Horde{/link} sich verteidigte. Daelin wurde in den Kämpfen vor den Mauern von Theramore erschlagen. Seine Tochter trauert, und die Seeleute, die ihm folgten, haben ihr nicht vergeben.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Jaina herrscht über {link:theramore-isle}Theramore{/link} von seiner Zitadelle aus. Die Stadt ist eine Zuflucht für das Volk des verlorenen Nordens und ein Tor der {link:alliance}Allianz{/link} nach {link:kalimdor}Kalimdor{/link}. Sie wahrt den Frieden mit {link:thrall}Thrall{/link}, so gut sie kann, während die Soldaten beider Seiten in der Wildnis aneinandergeraten.]=],
		},
	},
	chapters = {
		{
			title = "Der vermisste Diplomat",
			hint = "Folgt der Spur des vermissten Diplomaten nach Theramore.",
			text = [=[Die Spur eines entführten Gesandten führte von {link:stormwind-city}Stormwind{/link} zum Hafen von Menethil und von dort über das Meer in die {link:dustwallow-marsh}Marschen von Dustwallow{/link}. An ihrem Ende stand der Gefreite {link:private-hendel}Hendel{/link}, ein Soldat von {link:theramore-isle}Theramore{/link}, der sich an die {link:defias-brotherhood}Bruderschaft der Defias{/link} verkauft hatte. Als er entlarvt wurde, zog er seine Klinge. Jaina und ihre Wachen kamen, um ihn lebend zu fassen, denn ein toter Verräter erzählt nichts. Die Herrin von Theramore sprach denen, die die Wahrheit ans Licht gebracht hatten, ihren stillen Dank aus. Offen danken konnte sie ihnen nicht. Was Hendel über den verschwundenen König von Stormwind weiß, ist eine Sache für ihre Verhörer.]=],
		},
	},
	mentions = {
		{ text = "The Missing Diplomat" },
		{ text = "The Missing Diplomat" },
	},
	bonds = {
		{ id = "daelin-proudmoore", name = "Daelin Proudmoore", note = "ihr Vater" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "ihr Gefährte und ihre verlorene Liebe" },
		{ id = "thrall", name = "Thrall", note = "ihr Verbündeter im Frieden" },
		{ id = "aegwynn", name = "Aegwynn", note = "soll sie beraten haben" },
		{ id = "tapoke-slim-jahn", name = "Tapoke \"Slim\" Jahn", note = "half bei der Verschwörung, die ihre Wachen aufdeckten" },
	},
})

Translate("deDE", "khadgar", {
	title = "Khadgar",
	subtitle = "Lehrling des letzten Wächters",
	allegiance = "Kirin Tor · Allianz von Lordaeron",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Khadgar war ein junger Magier aus {link:dalaran}Dalaran{/link}, von den {link:kirin-tor}Kirin Tor{/link} ausgesandt, um {link:medivh}Medivh{/link}, dem letzten {link:the-night-watch}Wächter{/link} von {link:tirisfal-glades}Tirisfal{/link}, als Lehrling zu dienen. Er war der Erste, der erkannte, dass der Wächter selbst die {link:orcs}Orcs{/link} nach {link:azeroth}Azeroth{/link} gebracht hatte. Er kämpfte im {link:first-war}Ersten Krieg{/link} und im {link:second-war}Zweiten Krieg{/link}, und er wurde einer der großen Erzmagier seines Zeitalters. Er ging vor langer Zeit durch das {link:dark-portal}Dunkle Portal{/link}, und er ist nicht zurückgekehrt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Khadgar trug die Wahrheit aus {link:karazhan}Karazhan{/link} heraus. Ohne ihn hätte {link:stormwind-city}Stormwind{/link} vielleicht nie erfahren, wer sein wahrer Feind war. Im Zweiten Krieg stand er an der Seite von {link:anduin-lothar}Anduin Lothar{/link} als ein Anführer der {link:alliance}Allianz{/link}, und am Ende verschloss er den Weg zwischen den Welten um den Preis seiner eigenen Heimkehr.]=],
		},
		{
			title = "Karazhan",
			text = [=[Die Magier von {link:dalaran}Dalaran{/link} hatten lange gewünscht, die Geheimnisse von {link:karazhan}Medivhs Turm{/link} zu erfahren. Sie schickten Khadgar als seinen Lehrling, und sie trugen ihm auf zu beobachten. Der {link:the-night-watch}Wächter{/link} nahm ihn auf und unterrichtete ihn. Khadgar erfuhr bald, dass sein Meister lange Schweigen, seltsame Visionen und eine Dunkelheit in sich trug, von der er nicht sprechen wollte. Mit der Halborcin {link:garona}Garona{/link}, die als Gesandte der {link:horde}Horde{/link} in den Turm kam, entdeckte er, dass {link:medivh}Medivh{/link} selbst das Dunkle Portal geöffnet hatte. Die beiden trugen die Warnung zu König {link:llane-wrynn}Llane Wrynn{/link}. Dann erklomm Khadgar mit {link:anduin-lothar}Lothar{/link} Karazhan, um sich seinem Meister zu stellen. Medivh wurde erschlagen. In diesem Kampf alterte der junge Magier in einem Augenblick um viele Jahre, und er stieg mit dem Gesicht eines alten Mannes vom Turm herab.]=],
		},
		{
			title = "Der Zweite Krieg",
			text = [=[Khadgar ging mit {link:anduin-lothar}Lothar{/link} und den Verbannten von {link:stormwind-city}Stormwind{/link} nach Norden. In {link:lordaeron}Lordaeron{/link} war er einer der Leutnants des Streiters, zusammen mit dem Paladin {link:turalyon}Turalyon{/link}. Er bekämpfte die {link:horde}Horde{/link} überall in den nördlichen Königreichen und half, ihre Niederlage am {link:blackrock-mountain}Blackrock{/link} herbeizuführen. Als der Krieg gewonnen war, zerstörte die {link:alliance}Allianz{/link} das Dunkle Portal.]=],
		},
		{
			title = "Taten",
			text = [=[• Er diente als letzter Lehrling von {link:medivh}Medivh{/link} in {link:karazhan}Karazhan{/link}.
• Er deckte Medivhs Anteil am Kommen der {link:orcs}Orcs{/link} auf und warnte {link:llane-wrynn}König Llane{/link}.
• Er kämpfte an der Seite von {link:anduin-lothar}Anduin Lothar{/link}, als Medivh erschlagen wurde.
• Er diente im Zweiten Krieg als Leutnant der {link:alliance}Allianz{/link}.
• Er führte die Allianz nach dem Krieg jenseits des Dunklen Portals.]=],
		},
		{
			title = "Jenseits des Portals",
			text = [=[Einige Jahre nach dem Zweiten Krieg öffnete sich das Portal erneut. {link:orcs}Orcs{/link} kamen hindurch aus {red:draenor}Draenor{/red}, um Relikte der Macht zu stehlen, ausgesandt vom alten Schamanen {link:ner-zhul}Ner'zhul{/link}. Die {link:alliance}Allianz{/link} schickte ihnen eine Armee in die Heimatwelt der Orcs nach. Khadgar führte sie mit {link:turalyon}Turalyon{/link}. Ner'zhuls Zauber rissen Draenor auseinander. Um zu verhindern, dass der Untergang nach {link:azeroth}Azeroth{/link} überschwappte, entschieden die Anführer der Allianz, das Portal von der anderen Seite zu schließen. Sie wussten, dass sie nicht heimkehren konnten. Das Portal verstummte, und die Expedition war für ihr Volk verloren.]=],
		},
		{
			title = "Schicksal",
			text = [=[Seit das Portal geschlossen wurde, hat keine Nachricht von Khadgar die Königreiche erreicht. In den {link:blasted-lands}Verwüsteten Landen{/link} halten die Magier der {link:kirin-tor}Kirin Tor{/link} von der {link:nethergarde-keep}Burg Nethergarde{/link} aus Wacht über das zerstörte Tor, und sie haben ihn nicht vergessen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik der Königreiche erzählt, was aus Khadgar und seinen Gefährten jenseits des Portals wurde.]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Medivh", note = "sein Meister" },
		{ id = "garona", name = "Garona", note = "seine Verbündete in Karazhan" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "sein Befehlshaber" },
		{ id = "turalyon", name = "Turalyon", note = "sein Gefährte in zwei Kriegen" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "sein Feind jenseits des Portals" },
	},
})

Translate("deDE", "turalyon", {
	title = "Turalyon",
	subtitle = "Sieger des Zweiten Krieges",
	allegiance = "Ritter der Silbernen Hand · Allianz von Lordaeron",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Turalyon war ein junger Priester des {link:holy-light}Heiligen Lichts{/link}, der einer der ersten Paladine der Ritter der Silbernen Hand wurde. Er diente im {link:second-war}Zweiten Krieg{/link} als Leutnant von {link:anduin-lothar}Anduin Lothar{/link}. Als Lothar fiel, übernahm Turalyon seinen Befehl und gewann den Krieg. Danach führte er die {link:alliance}Allianz{/link} jenseits des {link:dark-portal}Dunklen Portals{/link}, und er kehrte nicht zurück.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Turalyon war es, der die dunkelste Stunde der {link:alliance}Allianz{/link} in einen Sieg verwandelte. Sein Angriff am {link:blackrock-mountain}Blackrock{/link} zerbrach die alte {link:horde}Horde{/link}, und der Frieden, den die nördlichen Königreiche eine Generation lang kannten, war sein Geschenk.]=],
		},
		{
			title = "Die Silberne Hand",
			text = [=[Turalyon war ein Priester der Kirche in {link:lordaeron}Lordaeron{/link}, als die Verbannten von {link:stormwind-city}Stormwind{/link} nach Norden kamen. {link:anduin-lothar}Lothar{/link} sah Stärke in ihm und machte ihn zu einem seiner Leutnants, zusammen mit dem Magier {link:khadgar}Khadgar{/link}. Turalyon zweifelte an sich und an seinem Glauben. Doch er gehörte zu den ersten Rittern, die Erzbischof {link:alonsus-faol}Alonsus Faol{/link} ausbildete, das Licht im Kampf zu führen, mit {link:uther-the-lightbringer}Uther dem Lichtbringer{/link}, {link:tirion-fordring}Tirion Fordring{/link} und einigen anderen. Er führte die Armeen der {link:alliance}Allianz{/link} im Norden gegen die {link:horde}Horde{/link}, und er lernte, der Macht zu vertrauen, die ihm gegeben worden war.]=],
		},
		{
			title = "Der Blackrock",
			text = [=[Am Ende des Krieges trieb die {link:alliance}Allianz{/link} die {link:horde}Horde{/link} nach Süden zum {link:blackrock-mountain}Blackrock{/link}. In der Schlacht am Fuß des Berges erschlug der Kriegshäuptling {link:orgrim-doomhammer}Orgrim Doomhammer{/link} {link:anduin-lothar}Lothar{/link}. Die Soldaten der Allianz wankten. Turalyon nahm das Schwert seines Befehlshabers auf und sammelte sie. Die Paladine riefen das Licht an, und die Horde wurde gebrochen. Doomhammer wurde gefangen genommen. Turalyon verfolgte die letzten {link:orcs}Orcs{/link} bis zum Dunklen Portal, und die Allianz zerstörte das Tor.]=],
		},
		{
			title = "Taten",
			text = [=[• Er gehörte zu den ersten Paladinen der Silbernen Hand.
• Er diente im Zweiten Krieg als Leutnant von {link:anduin-lothar}Anduin Lothar{/link}.
• Er sammelte die {link:alliance}Allianz{/link} nach Lothars Tod und gewann die Schlacht am {link:blackrock-mountain}Blackrock{/link}.
• Er trieb die {link:horde}Horde{/link} bis zum Dunklen Portal und sah es zerstört.
• Er führte die Armee der Allianz mit {link:khadgar}Khadgar{/link} nach {red:draenor}Draenor{/red}.]=],
		},
		{
			title = "Jenseits des Portals",
			text = [=[Einige Jahre später öffnete sich das Portal erneut, und {link:orcs}Orcs{/link} kamen hindurch, um für den Schamanen {link:ner-zhul}Ner'zhul{/link} Relikte der Macht zu stehlen. Turalyon führte die Armee der {link:alliance}Allianz{/link} mit {link:khadgar}Khadgar{/link} nach Draenor. Mit ihnen gingen die Waldläuferin Alleria Windrunner, die ältere Schwester von {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, und andere Helden des Krieges. Die Expedition bekämpfte die Orcs überall in ihrer zerbrochenen Welt. Als Ner'zhuls Zauber Draenor auseinanderzureißen begannen, schlossen ihre Anführer das Portal von der anderen Seite, damit der Untergang {link:azeroth}Azeroth{/link} nicht erreichte. Sie konnten nicht heimkehren.]=],
		},
		{
			title = "Schicksal",
			text = [=[Turalyon ist in den Königreichen nicht mehr gesehen worden, seit das Portal geschlossen wurde. Die Paladine des Nordens sprechen seinen Namen noch immer neben dem Uthers aus.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik der Königreiche verzeichnet, was aus Turalyon jenseits des Portals wurde.]=],
		},
	},
	bonds = {
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "sein Befehlshaber" },
		{ id = "khadgar", name = "Khadgar", note = "sein Gefährte in zwei Kriegen" },
		{ id = "uther-the-lightbringer", name = "Uther der Lichtbringer", note = "ein Bruder der Silbernen Hand" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "der Kriegshäuptling, den er besiegte" },
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "weihte ihn" },
	},
})

Translate("deDE", "tirion-fordring", {
	title = "Tirion Fordring",
	subtitle = "Der verbannte Paladin",
	found = [=[Eine einsame Hütte am Fluss am westlichen Rand der Östlichen Pestländer]=],
	hint = [=[Sucht den Einsiedler, der bei einer Hütte am westlichen Rand der Östlichen Pestländer angelt.]=],
	allegiance = "Keine (einst die Ritter der Silbernen Hand)",
	aliases = { "Tirion" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tirion Fordring war einst der Herr der Burg Mardenholde und einer der ersten Paladine der Silbernen Hand. Weil er einen {link:orcs}Orc{/link} verteidigte, wurde er seiner Ländereien und Titel beraubt und ins Exil getrieben. Nun lebt er allein in einer Hütte in den {link:eastern-plaguelands}Östlichen Pestländern{/link}, ein alter Mann in einem Land der Toten. Sein Sohn führt den {link:scarlet-crusade}Scharlachroten Kreuzzug{/link} in {link:hearthglen}Hearthglen{/link} und glaubt, sein Vater sei lange tot.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Tirion ist ein Mann des Lichts, der seine Ehre bewahrte, als sein Orden und sein Königreich es nicht taten. Wenige in {link:lordaeron}Lordaeron{/link} erinnern sich an ihn. Doch die {link:orcs}Orcs{/link}, die seine Geschichte kennen, ehren ihn, und die Geschichte seines Falls spricht zu jedem, der je zwischen dem Gesetz und dem Richtigen wählen musste.]=],
		},
		{
			title = "Die Silberne Hand",
			text = [=[Tirion gehörte zu den ersten Rittern, die Erzbischof {link:alonsus-faol}Alonsus Faol{/link} ausbildete, mit {link:uther-the-lightbringer}Uther dem Lichtbringer{/link} und {link:turalyon}Turalyon{/link}. Er bekämpfte die {link:horde}Horde{/link} im {link:second-war}Zweiten Krieg{/link}. Nach dem Krieg herrschte er von der Burg Mardenholde aus über die Ländereien von {link:hearthglen}Hearthglen{/link}, mit seiner Frau Karandra und seinem Sohn {link:taelan-fordring}Taelan{/link}.]=],
		},
		{
			title = "Der Prozess",
			text = [=[Eines Tages stieß Tirion auf einen alten Orckrieger, der sich in den Ruinen nahe seinen Ländereien versteckte. Es war {link:eitrigg}Eitrigg{/link}. Der {link:orcs}Orc{/link} hätte ihn töten können, und er verschonte ihn stattdessen. Tirion sah Ehre in ihm und ließ ihn gehen. Als seine eigenen Soldaten kamen, um den Orc zu töten, verteidigte Tirion ihn. Dafür wurde ihm wegen Verrats der Prozess gemacht. Er wurde seiner Ländereien und Titel beraubt und aus dem Orden verbannt. Seine Frau erzählte ihrem Sohn, er sei gestorben, und {link:taelan-fordring}Taelan{/link} wurde an das falsche Grab seines Vaters geführt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er gehörte zu den ersten Paladinen der Ritter der Silbernen Hand.
• Er bekämpfte die {link:horde}Horde{/link} im Zweiten Krieg.
• Er herrschte über die Burg Mardenholde und die Ländereien um {link:hearthglen}Hearthglen{/link}.
• Er verschonte den {link:orcs}Orc{/link} {link:eitrigg}Eitrigg{/link} und verteidigte ihn gegen seine eigenen Männer.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Tirion lebt allein am Fluss, fern jeder Straße. Sein Sohn {link:taelan-fordring}Taelan{/link} wuchs zum Paladin heran und ist nun Hochlord des Scharlachroten Kreuzzugs in {link:hearthglen}Hearthglen{/link}, gebunden an einen Orden, der seinen Weg verloren hat. {link:eitrigg}Eitrigg{/link} dient {link:thrall}Thrall{/link} in {link:orgrimmar}Orgrimmar{/link} und hat den Mann nicht vergessen, der ihn rettete.]=],
		},
	},
	chapters = {
		{
			title = "Erlösung",
			hint = [=[Setzt Euch zu dem alten Mann am Fluss und hört seine Geschichte.]=],
			text = [=[Tirion bat seinen Gast nur, sich zu setzen und zuzuhören. Er erzählte von seinem Fall und von seinem Sohn, der ohne ihn aufgewachsen war. Er bat nicht darum, seinen eigenen Namen reinzuwaschen. Er bat darum, {link:taelan-fordring}Taelan{/link} vor dem zu retten, was der Kreuzzug aus ihm gemacht hatte.]=],
		},
		{
			title = "Von vergessenen Erinnerungen",
			hint = [=[Holt ein Spielzeug aus einem falschen Grab im Süden der Pestländer.]=],
			text = [=[Als {link:taelan-fordring}Taelan{/link} sieben war, schenkte ihm sein Vater einen kleinen Kriegshammer, eine Nachbildung seines eigenen. Nach Tirions Verbannung vergrub der Knabe ihn am falschen Grab seines Vaters im {link:the-undercroft}Tiefgewölbe{/link}. Dort hatte er seitdem gelegen, und Tirion bat darum, ihn zurückzubekommen.]=],
		},
		{
			title = "Von verlorener Ehre",
			hint = "Holt zurück, was Taelan in Northdale niederwarf.",
			text = [=[Als {link:uther-the-lightbringer}Uther{/link} fiel und die Silberne Hand vernichtet wurde, kämpfte der junge {link:taelan-fordring}Taelan{/link} weiter, so lange er konnte. Im Weiler {link:northdale}Northdale{/link} leistete er ein letztes Gefecht, und dort warf er das Banner des Ordens zu Boden und kehrte ihm den Rücken. Tirion betrachtete das zerrissene Banner und erinnerte sich an den Tag, an dem er seinen eigenen Eid schwor.]=],
		},
		{
			title = "In Träumen",
			hint = "Bringt Taelan zu seinem Vater.",
			text = [=[{link:taelan-fordring}Taelan{/link} hatte jahrelang von seinem Vater geträumt. In Erinnerung an das, was er gewesen war, verließ er {link:hearthglen}Hearthglen{/link}, um ihn zu finden. Der Kreuzzug jagte ihn auf der Straße, und der Großinquisitor Isillien erschlug ihn vor den Augen seines Vaters. In seiner Trauer verkündete Tirion, dass der Orden, dem er gedient hatte, nicht tot sei. Er ernannte sich selbst zum Hochlord einer neuen Silbernen Hand, wiedergeboren aus der alten.]=],
		},
	},
	mentions = {
		{ text = "Redemption" },
		{ text = "Of Forgotten Memories" },
		{ text = "Of Lost Honor" },
		{ text = "Von Liebe und Familie" },
		{ text = "In Dreams" },
	},
	bonds = {
		{ id = "eitrigg", name = "Eitrigg", note = "der Orc, den er verschonte" },
		{ id = "uther-the-lightbringer", name = "Uther der Lichtbringer", note = "ein Bruder der Silbernen Hand" },
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "sein Lehrer im Licht" },
		{ id = "turalyon", name = "Turalyon", note = "ein Bruder der Silbernen Hand" },
	},
})

Translate("deDE", "garona", {
	title = "Garona",
	subtitle = "Die Halborcin",
	allegiance = "Unbekannt (einst der Schattenrat)",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Garona war eine Halborcin gemischten Blutes, eine Spionin und Gesandte der {link:horde}Horde{/link} im {link:first-war}Ersten Krieg{/link}. Der Hexenmeister {link:gul-dan}Gul'dan{/link} schickte sie zum Turm von {link:medivh}Medivh{/link}. Dort freundete sie sich mit dem jungen Magier {link:khadgar}Khadgar{/link} an, und sie trat in den Dienst von König {link:llane-wrynn}Llane Wrynn{/link} von {link:stormwind-city}Stormwind{/link}. Sie ermordete ihn auch.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Garona half, die Wahrheit über Medivhs Verrat nach {link:stormwind-city}Stormwind{/link} zu bringen, und sie führte den Schlag, der seinen König tötete. Beide Taten waren ihre, und keine war ganz ihre eigene.]=],
		},
		{
			title = "Gesandte und Spionin",
			text = [=[Garona wurde unter den {link:orcs}Orcs{/link} wegen ihres gemischten Blutes verachtet, und sie lernte früh, durch ihren Verstand zu überleben. Der {link:shadow-council}Schattenrat{/link} von {link:gul-dan}Gul'dan{/link} bediente sich ihrer. Sie kam als Gesandte der {link:horde}Horde{/link} zum {link:the-night-watch}Wächter{/link} nach {link:karazhan}Karazhan{/link}. Dort erfuhren sie und {link:khadgar}Khadgar{/link}, dass {link:medivh}Medivh{/link} selbst die Orcs nach {link:azeroth}Azeroth{/link} gebracht hatte. Sie stand mit Khadgar und {link:anduin-lothar}Anduin Lothar{/link} zusammen, als der Wächter erschlagen wurde. Danach trat sie in {link:stormwind-city}Stormwind{/link} in Dienst und wurde eine vertraute Beraterin des Königs.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie diente als Gesandte der {link:horde}Horde{/link} bei {link:medivh}Medivh{/link} in {link:karazhan}Karazhan{/link}.
• Sie half {link:khadgar}Khadgar{/link}, Medivhs Verrat aufzudecken.
• Sie war beim Tod des Wächters zugegen.
• Sie erschlug {link:llane-wrynn}König Llane{/link} Wrynn in seiner eigenen Burg.]=],
		},
		{
			title = "Schicksal",
			text = [=[Garonas Geist war nicht ihr eigener. Die Hexenmeister des Schattenrats hielten eine verborgene Macht über ihren Willen. Als {link:orgrim-doomhammer}Orgrim Doomhammer{/link} {link:stormwind-city}Stormwind{/link} zum letzten Mal belagerte, tötete sie {link:llane-wrynn}Llane{/link} in seinem Gemach, und der junge Prinz {link:varian-wrynn}Varian Wrynn{/link} sah es. Dann floh sie. Niemand in den Königreichen weiß, wohin sie ging.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Wohin Garona seit dem Fall von {link:stormwind-city}Stormwind{/link} gegangen ist und ob sie noch lebt, sagen die Chroniken nicht.]=],
		},
	},
	bonds = {
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "ihr König und ihr Opfer" },
		{ id = "khadgar", name = "Khadgar", note = "ihr Freund in Karazhan" },
		{ id = "medivh", name = "Medivh", note = "der Wächter, bei dem sie als Gesandte diente" },
		{ id = "gul-dan", name = "Gul'dan", note = "ihr Herr" },
	},
})

Translate("deDE", "alexstrasza", {
	title = "Alexstrasza",
	subtitle = "Königin der roten Drachen",
	allegiance = "Roter Drachenschwarm",
	aliases = { "Alexstrasza die Lebensbinderin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Alexstrasza ist der Aspekt des roten Drachenschwarms, die Drachenkönigin, Hüterin des Lebens. In den alten Tagen erhielt sie von den Schöpfern der Welt Macht über alles Lebendige. Sie wacht über {link:azeroth}Azeroth{/link}, seit bevor die Elfen ihre ersten Städte bauten. In den Jahren des {link:second-war}Zweiten Krieges{/link} war sie eine Gefangene der {link:orcs}Orcs{/link}, und ihre Kinder wurden zu Kriegswaffen gemacht.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Kein Volk hat mehr unter dem Verrat von {link:deathwing}Todesschwinge{/link} gelitten als die roten Drachen. Ihre Gefangenschaft in {link:grim-batol}Grim Batol{/link} gab der {link:horde}Horde{/link} ihre Drachen, und sie ist noch immer der Grund für den Hass zwischen dem roten Schwarm und den {link:orcs}Orcs{/link} des {link:dragonmaw-clan}Dragonmawklans{/link}.]=],
		},
		{
			title = "Die Aspekte",
			text = [=[In den alten Tagen wurden fünf große Drachen erwählt, um die Welt zu hüten. Alexstrasza, die größte von ihnen, wurde zur Hüterin allen Lebens gemacht. {link:deathwing}Neltharion{/link} der Erdwächter war ihr Gefährte unter ihnen. Im {link:war-of-the-ancients}Krieg der Ahnen{/link} überredete er die Aspekte, einen Teil ihrer Macht seiner großen Scheibe aus Gold, der Drachenseele, zu geben, und wandte sie dann gegen sie. Die Drachen wurden zerstreut, und der rote Schwarm litt schrecklich. Alexstrasza vergaß es nie.]=],
		},
		{
			title = "Grim Batol",
			text = [=[Im Zweiten Krieg fiel die Drachenseele in die Hände der {link:orcs}Orcs{/link} des Dragonmawklans. Mit ihrer Macht nahmen sie Alexstrasza gefangen und banden sie unter dem Berg {link:grim-batol}Grim Batol{/link} im {link:wetlands}Sumpfland{/link}. Sie nahmen ihre Eier, sobald sie gelegt waren, und sie zogen ihre Jungen als Kriegsreittiere auf. Die roten Drachen flogen für die {link:horde}Horde{/link} gegen die {link:alliance}Allianz{/link} und verbrannten die Wälder von {link:quel-thalas}Quel'Thalas{/link} und die Städte des Nordens.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie wurde in den alten Tagen zum Aspekt des Lebens erwählt.
• Sie wurde im {link:war-of-the-ancients}Krieg der Ahnen{/link} von {link:deathwing}Neltharion{/link} verraten.
• Sie wurde vom {link:dragonmaw-clan}Dragonmawklan{/link} in {link:grim-batol}Grim Batol{/link} gefangen gehalten.
• Sie wurde befreit, und sie sah die Drachenseele zerstört.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Lange nach dem Krieg hielt der {link:dragonmaw-clan}Dragonmawklan{/link} die Königin noch immer fest. {link:deathwing}Todesschwinge{/link} kam wegen ihrer Eier nach {link:grim-batol}Grim Batol{/link}, um ihre Kinder für sich zu nehmen. Eine kleine Schar von Helden und Drachen befreite Alexstrasza. Die Drachenseele wurde zerstört, und ihre Macht kehrte zurück. Die roten Drachen wandten sich gegen ihre Kerkermeister und vertrieben Todesschwinge. Der Dragonmawklan klammert sich noch immer an das {link:wetlands}Sumpfland{/link}, und die roten Drachen jagen ihn noch immer. Wo die Drachenkönigin selbst nun weilt, wissen wenige Sterbliche.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Die Chroniken der Königreiche sagen wenig darüber, wohin die Drachenkönigin seit ihrer Befreiung gegangen ist.]=],
		},
	},
	bonds = {
		{ id = "deathwing", name = "Todesschwinge", note = "ihr Mitaspekt und ihr Verräter" },
		{ id = "queen-azshara", name = "Königin Azshara", note = "in deren Krieg die Aspekte verraten wurden" },
	},
})

Translate("deDE", "cenarius", {
	title = "Cenarius",
	subtitle = "Herr des Waldes",
	allegiance = "Die Wälder Kalimdors · Zirkel des Cenarius",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Cenarius war ein Halbgott der Wildnis, der Herr der Wälder von {link:kalimdor}Kalimdor{/link}. Die {link:night-elves}Nachtelfen{/link} hielten ihn für ein Kind ihrer Mondgöttin Elune. Er war der Lehrer von {link:malfurion-stormrage}Malfurion Stormrage{/link} und der Vater der druidischen Künste unter den Sterblichen. Er fiel im {link:third-war}Dritten Krieg{/link}, erschlagen von {link:grom-hellscream}Grom Hellscream{/link} in den Wäldern des {link:ashenvale}Eschentals{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Jeder Druide, der auf der Welt wandelt, geht einen Pfad, den Cenarius eröffnete. Der {link:cenarion-circle}Zirkel des Cenarius{/link}, der Druiden der {link:night-elves}Nachtelfen{/link} und der {link:tauren}Tauren{/link} vereint, trägt seinen Namen. Sein Tod war eine Wunde für die Wälder Kalimdors, und die Nachtelfen haben ihn nicht vergeben.]=],
		},
		{
			title = "Der erste Druide",
			text = [=[Im Zeitalter vor dem {link:war-of-the-ancients}Krieg der Ahnen{/link} wohnte Cenarius in den Hainen des Berges Hyjal. Er nahm den jungen {link:malfurion-stormrage}Malfurion{/link} als Schüler an und lehrte ihn, die Mächte der Natur zu formen. Als die {link:burning-legion}Brennende Legion{/link} durch den {link:well-of-eternity}Brunnen der Ewigkeit{/link} kam, führte Cenarius die uralten Geister des Waldes an der Seite der {link:night-elves}Nachtelfen{/link} in die Schlacht. Nach der {link:great-sundering}Großen Teilung{/link} nahmen die Druiden von Malfurions Orden seine Lehren auf und bewahrten sie zehntausend Jahre lang. Sein Name lebte im Horn des Cenarius fort, das Malfurion eines Tages am Fuß des Weltenbaums blasen sollte.]=],
		},
		{
			title = "Seine Kinder",
			text = [=[Cenarius hatte viele Kinder. Die Dryaden und die Bewahrer des Hains sollen die seinen sein. Sein Sohn Zaetar war der Vater der ersten {link:centaurs}Zentauren{/link}, eines Volkes, das sich heute an wenig von ihm erinnert außer an seinen Zorn. Sein Sohn {link:keeper-remulos}Remulos{/link} hütet die heilige Lichtung von {link:moonglade}Moonglade{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er lehrte {link:malfurion-stormrage}Malfurion{/link} und die ersten Druiden die Wege der Natur.
• Er führte die Geister des Waldes im {link:war-of-the-ancients}Krieg der Ahnen{/link}.
• Er wachte zehntausend Jahre lang über die Wälder Kalimdors.
• Er bekämpfte die {link:orcs}Orcs{/link}, die kamen, um die Bäume des Eschentals zu schlagen.
• Das Horn, das seinen Namen trägt, rief in der {link:battle-of-mount-hyjal}Schlacht um den Berg Hyjal{/link} die Geister der Ahnen gegen {link:archimonde}Archimonde{/link}.]=],
		},
		{
			title = "Schicksal",
			text = [=[Im Dritten Krieg kamen die {link:orcs}Orcs{/link} des Warsongklans ins {link:ashenvale}Eschental{/link}, um Holz zu schlagen. Die {link:night-elves}Nachtelfen{/link} bekämpften sie, und Cenarius kam, um seinen Wald zu verteidigen. Die Orcs konnten ihm nicht standhalten. In ihrer Verzweiflung tranken {link:grom-hellscream}Grom Hellscream{/link} und seine Krieger aus einer Quelle, die das Blut von {link:mannoroth}Mannoroth{/link} verunreinigt hatte, und die alte Wut kam über sie. In dieser Raserei erschlugen sie den Halbgott. Cenarius ist tot. Seine Druiden ehren ihn noch immer, und seine Kinder hüten noch immer seine Haine.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Ob irgendeine Macht des Cenarius seinen Tod überdauerte, sagen die Chroniken nicht.]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "sein Schüler" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "sein Mörder" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "Bruder seines Schülers" },
		{ id = "mannoroth", name = "Mannoroth", note = "dessen Blut seine Mörder in den Wahnsinn trieb" },
	},
})

Translate("deDE", "kil-jaeden", {
	title = "Kil'jaeden",
	subtitle = "Der Betrüger",
	aliases = { "Kil'jaeden der Betrüger" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kil'jaeden der Betrüger ist einer der großen Fürsten der {link:burning-legion}Brennenden Legion{/link}, nur dem Willen von {link:sargeras}Sargeras{/link} untertan. Er war einst mit {link:archimonde}Archimonde{/link} ein Anführer der Eredar, und er nahm das Angebot des dunklen Titanen an, wie Archimonde es tat. Er ist ein Meister der Lüge. Kil'jaeden war es, der die {link:orcs}Orcs{/link} von {red:draenor}Draenor{/red} verdarb, und er war es, der den {red:lich-king}Lichkönig{/red} erschuf.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Wenigen der Unglücke der letzten Generation fehlt die Hand des Betrügers. Durch {link:ner-zhul}Ner'zhul{/link} und {link:gul-dan}Gul'dan{/link} machte er die {link:orcs}Orcs{/link} zu einer Waffe. Durch den Lichkönig entfesselte er die {link:scourge}Geißel{/link} auf {link:lordaeron}Lordaeron{/link}. Anders als {link:archimonde}Archimonde{/link} ist er nie besiegt worden.]=],
		},
		{
			title = "Die Eredar",
			text = [=[Vor langer Zeit wurden die Eredar von drei Anführern beherrscht: Kil'jaeden, {link:archimonde}Archimonde{/link} und Velen. {link:sargeras}Sargeras{/link} kam mit Versprechungen von Wissen und Macht zu ihnen. Kil'jaeden und Archimonde nahmen an, und sie und ihr Volk wurden zu Dämonen verzerrt. Velen lehnte ab und floh mit seinen Anhängern. Kil'jaeden hasste ihn dafür, und er schwor, Velens Volk zu jagen, wohin es auch ging.]=],
		},
		{
			title = "Die Orcs",
			text = [=[Velens Volk, die Draenei, kam schließlich nach Draenor, wo die {link:orcs}Orcs{/link} lebten. Kil'jaeden fand sie dort. Er ging in der Gestalt eines Geistes der Ahnen zum alten Schamanen {link:ner-zhul}Ner'zhul{/link}, und er sagte ihm, die Draenei schmiedeten Ränke gegen sein Volk. Als Ner'zhul an ihm zu zweifeln begann, wandte sich der Betrüger an seinen Lehrling {link:gul-dan}Gul'dan{/link} und lehrte ihn die Künste der {link:fel-magic}Teufelsmagie{/link}. Durch Gul'dan gab er den Orcs das Blut von {link:mannoroth}Mannoroth{/link}, band sie an die Legion und hetzte sie auf die Draenei.]=],
		},
		{
			title = "Taten",
			text = [=[• Er nahm das Angebot von {link:sargeras}Sargeras{/link} an und wurde ein Fürst der Legion.
• Er täuschte {link:ner-zhul}Ner'zhul{/link} und brachte die {link:orcs}Orcs{/link} gegen die Draenei auf.
• Er lehrte {link:gul-dan}Gul'dan{/link} die Künste der {link:fel-magic}Teufelsmagie{/link}.
• Er machte Ner'zhul zum Lichkönig.
• Er sandte den Lichkönig aus, um {link:azeroth}Azeroth{/link} für die Legion vorzubereiten.]=],
		},
		{
			title = "Der Lichkönig",
			text = [=[Als {link:ner-zhul}Ner'zhul{/link} vor dem Untergang Draenors floh, wartete Kil'jaeden auf ihn. Er riss dem Schamanen den Leib fort und band seinen Geist in eine Rüstung und einen Helm. Er versiegelte ihn in Eis und schleuderte ihn auf {red:northrend}Nordend{/red} hinab, mit dem Befehl, eine Seuche zu verbreiten, die die Welt schwächen sollte, bevor die Legion kam. Der Lichkönig tat es. Als {link:archimonde}Archimonde{/link} am {link:mount-hyjal}Berg Hyjal{/link} fiel, erfuhr der Betrüger, dass sein Diener begonnen hatte, seine Ketten abzustreifen.]=],
		},
		{
			title = "Schicksal",
			text = [=[Kil'jaeden hat {link:azeroth}Azeroth{/link} nicht betreten. Nach dem Dritten Krieg suchte er den Lichkönig durch andere vernichten zu lassen. Der Lichkönig besteht fort, und der Betrüger wacht noch immer von jenseits der Welt.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Die Chroniken sagen nicht, wo Kil'jaeden weilt oder was er jetzt plant.]=],
		},
	},
	bonds = {
		{ id = "archimonde", name = "Archimonde", note = "ein Fürst der Legion wie er" },
		{ id = "sargeras", name = "Sargeras", note = "sein Herr" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "der Schamane, den er täuschte und zum Lichkönig machte" },
		{ id = "gul-dan", name = "Gul'dan", note = "sein Diener unter den Orcs" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "den er gegen den Lichkönig sandte" },
	},
})

Translate("deDE", "sargeras", {
	title = "Sargeras",
	subtitle = "Herr der Brennenden Legion",
	aliases = { "Der dunkle Titan" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Sargeras ist der Herr der {link:burning-legion}Brennenden Legion{/link}, ein gefallener Titan, der die ganze Schöpfung auslöschen will. Er war einst der größte Streiter der Titanen, der Erbauer der Welten, und er bekämpfte die Dämonen des Wirbelnden Nethers unzählige Zeitalter lang. Mit der Zeit verzweifelte er an seinem Werk. Er befreite die Dämonen, die er eingekerkert hatte, sammelte sie zu einem Heer und wandte es gegen jede Welt, die die Titanen geformt hatten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Jeder Krieg, den die Legion auf {link:azeroth}Azeroth{/link} geführt hat, wurde im Namen von Sargeras geführt. Er griff dreimal nach der Welt: durch {link:queen-azshara}Königin Azshara{/link}, durch {link:aegwynn}Aegwynn{/link} und ihren Sohn {link:medivh}Medivh{/link} und durch die {link:orcs}Orcs{/link}, die er an seinen Willen band. Sein Schatten liegt hinter dem {link:war-of-the-ancients}Krieg der Ahnen{/link}, dem {link:first-war}Ersten Krieg{/link} und dem {link:third-war}Dritten Krieg{/link}.]=],
		},
		{
			title = "Der gefallene Titan",
			text = [=[Die Geschichtswerke sagen, dass Sargeras länger, als ein Sterblicher ermessen kann, Dämonen durch die Große Dunkelheit jagte. Was er dort sah, wandelte sein Herz. Er kam zu der Überzeugung, dass die Schöpfung selbst fehlerhaft sei und nicht geheilt werden könne. Er ließ die Dämonen frei, die er gefangen hatte, und er verdarb die Eredar durch {link:archimonde}Archimonde{/link} und {link:kil-jaeden}Kil'jaeden{/link}, und so wurde die Legion geboren.]=],
		},
		{
			title = "Azeroth",
			text = [=[Vor zehntausend Jahren zogen {link:queen-azshara}Königin Azshara{/link} und ihre Hochgeborenen mit der Macht des {link:well-of-eternity}Brunnens der Ewigkeit{/link} seinen Blick auf sich. Sargeras sandte seine Legion durch ihr Portal, und er suchte selbst in die Welt einzutreten. Der Brunnen wurde zerstört, bevor er es konnte. Zeitalter später erschien er der Wächterin {link:aegwynn}Aegwynn{/link} in einem gewaltigen Sturm in {red:northrend}Nordend{/red}. Sie erschlug seinen Avatar und versiegelte dessen Leib in einem {link:the-sepulcher}Grabmal{/link} unter dem Meer. Sein Geist verbarg sich in ihr und ging in ihren ungeborenen Sohn über. Durch {link:medivh}Medivh{/link} öffnete der dunkle Titan das {link:dark-portal}Dunkle Portal{/link} und brachte die {link:orcs}Orcs{/link} nach {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er war einst der Streiter der Titanen.
• Er befreite die Dämonen, die er eingekerkert hatte, und gründete die {link:burning-legion}Brennende Legion{/link}.
• Er verdarb die Eredar durch {link:archimonde}Archimonde{/link} und {link:kil-jaeden}Kil'jaeden{/link}.
• Er flüsterte {link:azshara}Azshara{/link} zu und trat beinahe in die Welt ein.
• Er verbarg sich in {link:aegwynn}Aegwynn{/link} und {link:medivh}Medivh{/link} und öffnete durch ihn das Dunkle Portal.]=],
		},
		{
			title = "Schicksal",
			text = [=[Sargeras hat {link:azeroth}Azeroth{/link} nie in seiner wahren Gestalt betreten. Sein Avatar liegt in seinem {link:the-sepulcher}Grabmal{/link} unter dem Meer, das der Hexenmeister {link:gul-dan}Gul'dan{/link} emporhob und zu seinem eigenen Tod betrat. Als {link:medivh}Medivh{/link} erschlagen wurde, war der Griff des dunklen Titanen um die Welt gebrochen. Doch die Legion, die er führt, bleibt, und ihre Fürsten haben ihren Hunger nach dieser Welt nicht aufgegeben.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Was aus dem Geist von Sargeras wurde, als {link:medivh}Medivh{/link} starb, können die Chroniken der Königreiche nicht sagen.]=],
		},
	},
	bonds = {
		{ id = "archimonde", name = "Archimonde", note = "sein Leutnant" },
		{ id = "kil-jaeden", name = "Kil'jaeden", note = "sein Leutnant" },
		{ id = "aegwynn", name = "Aegwynn", note = "erschlug seinen Avatar" },
		{ id = "medivh", name = "Medivh", note = "sein Gefäß" },
		{ id = "queen-azshara", name = "Königin Azshara", note = "seine Dienerin" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "empfing sein Geschenk" },
	},
})

Translate("deDE", "mannoroth", {
	title = "Mannoroth",
	subtitle = "Der Zerstörer",
	aliases = { "Mannoroth der Zerstörer" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Mannoroth der Zerstörer war ein Grubenlord der {link:burning-legion}Brennenden Legion{/link}, ein turmhoher Dämon aus Horn und Hauer. Er führte die Armeen der Legion im {link:war-of-the-ancients}Krieg der Ahnen{/link}. Später band sein Blut die {link:orcs}Orcs{/link} von {red:draenor}Draenor{/red} an die Legion. Er wurde im {link:ashenvale}Eschental{/link} von {link:grom-hellscream}Grom Hellscream{/link} erschlagen, dem ersten Orc, der es trank.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Der Fluch der {link:orcs}Orcs{/link} war Mannoroths Blut. Es gab ihnen Stärke und Raserei, und es machte sie zu Sklaven. Sein Tod befreite sie, und die {link:horde}Horde{/link} von {link:thrall}Thrall{/link} wurde dadurch frei geboren.]=],
		},
		{
			title = "Das Blut",
			text = [=[Im {link:war-of-the-ancients}Krieg der Ahnen{/link} befehligte Mannoroth die Dämonen, die durch den {link:well-of-eternity}Brunnen der Ewigkeit{/link} strömten. Als sich die Legion Draenor zuwandte, versammelte der Hexenmeister {link:gul-dan}Gul'dan{/link} die Häuptlinge der {link:orcs}Orcs{/link} und bot ihnen einen Kelch mit dem Blut des Grubenlords an. Grom trank als Erster, und die anderen folgten. Ihr Volk wurde zu einer {link:horde}Horde{/link} der Wut, gebunden an den Willen der Legion. Lange danach kam Mannoroth im {link:third-war}Dritten Krieg{/link} ins {link:ashenvale}Eschental{/link}. Als Grom und seine Warsong daran verzweifelten, die Verteidiger des Waldes zu schlagen, tranken sie aus einer Quelle, die Mannoroth mit seinem Blut verunreinigt hatte. In der Raserei, die folgte, erschlugen sie {link:cenarius}Cenarius{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führte die Armeen der Legion im {link:war-of-the-ancients}Krieg der Ahnen{/link}.
• Sein Blut band die {link:orcs}Orcs{/link} von Draenor an die Legion.
• Er verunreinigte eine Quelle im {link:ashenvale}Eschental{/link} und versklavte die Warsong ein zweites Mal.]=],
		},
		{
			title = "Schicksal",
			text = [=[{link:thrall}Thrall{/link} und Grom gingen gemeinsam, um sich dem Grubenlord in einer Schlucht des Eschentals zu stellen. Mannoroth streckte Thrall nieder. Grom stürmte allein vor und trieb seine Axt in die Brust des Dämons. Mannoroth starb, und der Fluch über den {link:orcs}Orcs{/link} war gebrochen. Grom starb an seinen Wunden. Die Schlucht heißt noch immer {link:demon-fall-canyon}Demonfall-Canyon{/link}.]=],
		},
	},
	bonds = {
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "trank als Erster sein Blut und erschlug ihn" },
		{ id = "gul-dan", name = "Gul'dan", note = "gab den Orcs sein Blut" },
		{ id = "archimonde", name = "Archimonde", note = "ein Fürst der Legion wie er" },
		{ id = "cenarius", name = "Cenarius", note = "erschlagen von denen, die sein Blut in den Wahnsinn trieb" },
		{ id = "thrall", name = "Thrall", note = "bekämpfte ihn mit Grom" },
	},
})
